// haengt in Vanilla an der Sichtweite-Einstellung; hier steht er auf 1.
const DISPLAY_VIEW_RANGE_BLOCKS: f64 = 64.0;

// Eine fertig aufbereitete Weltbeschriftung (s. App::build_world_labels). Fasst die beiden
// Quellen -- text_display-Entity und Namensschild -- auf eine Form zusammen, damit das
// Zeichnen sie nicht mehr unterscheiden muss.
struct WorldLabel<'a> {
    // Der Wortlaut, noch ungetrennt. Als Verweis statt als Kopie: das Zerlegen in Zeilen
    // kostet Allokationen und passiert deshalb erst NACH der Entfernungs- und
    // Sichtbarkeitspruefung -- eine Beschriftung hinter einer Wand soll gar nichts kosten.
    // Cow, weil die beiden Quellen verschieden liegen: Display-Text und Custom-Name stehen
    // schon als Abschnitte in der Entity (geliehen), der Spielername aus der Tabellenliste
    // ist eine nackte Zeichenkette und wird hier erst zu einem Abschnitt gemacht (eigen).
    spans: std::borrow::Cow<'a, [protocol::nbt::TextSpan]>,
    // Weltpunkt, an dem die Beschriftung haengt.
    anchor: DVec3,
    // Zusaetzliche Skalierung aus der AffineTransformation des Displays (1.0 = Vanillas
    // Grundgroesse).
    world_scale: f32,
    // ARGB. Alpha 0 = kein Hintergrund.
    background: i32,
    opacity: u8,
    see_through: bool,
    // Rand um die Schrift. Text-Displays: ihr Schatten-Flag (Vanilla zeichnet sie sonst ohne);
    // Namensschilder: immer, s. text_shadow_style.
    shadow: bool,
    align: LabelAlign,
    // true = der Block sitzt UEBER dem Anker (Text-Display), false = mittig darauf
    // (Namensschild).
    above_anchor: bool,
    // Umbruchbreite in Schriftpixeln; INFINITY = nicht umbrechen.
    line_width: f32,
    max_distance: f64,
    // Nur Text-Displays: Entity-Position (augenrelativ) * Billboard-Drehung *
    // AffineTransformation -- also Vanillas Matrixstapel bis vor die Text-Skalierung. Solche
    // Beschriftungen liegen als echte Flaeche in der Welt (s. App::build_display_text);
    // Namensschilder (None) stehen immer parallel zum Bildschirm.
    display_matrix: Option<glam::Mat4>,
}

// JOMLs Matrix4f.rotate(Quaternionfc) als Drehmatrix -- bewusst die Formel selbst statt
// glam::Mat4::from_quat: Vanilla normalisiert die vom Server geschickten Quaternionen nicht,
// und JOML rechnet mit dem UNnormalisierten Wert (eine nicht normierte Quaternion skaliert
// dann mit). glam setzt eine normierte voraus.
fn joml_quat_matrix(q: [f32; 4]) -> glam::Mat4 {
    let [x, y, z, w] = q;
    let (w2, x2, y2, z2) = (w * w, x * x, y * y, z * z);
    let (dzw, dxy, dxz, dyw, dyz, dxw) = (2.0 * z * w, 2.0 * x * y, 2.0 * x * z, 2.0 * y * w, 2.0 * y * z, 2.0 * x * w);
    glam::Mat4::from_cols(
        glam::Vec4::new(w2 + x2 - z2 - y2, dxy + dzw, dxz - dyw, 0.0),
        glam::Vec4::new(dxy - dzw, y2 - z2 + w2 - x2, dyz + dxw, 0.0),
        glam::Vec4::new(dyw + dxz, dyz - dxw, z2 - y2 - x2 + w2, 0.0),
        glam::Vec4::W,
    )
}

// DisplayEntityRenderer.getBillboardRotation: rotationYXZ(-yaw, pitch, 0), je nach Modus mit
// den Winkeln des Entities oder der Kamera. 0 FIXED = feste Flaeche, 1 VERTICAL = dreht sich
// nur um die Hochachse mit, 2 HORIZONTAL = nur im Nick, 3 CENTER = wie ein Namensschild.
fn display_billboard_matrix(mode: u8, yaw: f32, pitch: f32, cam_yaw: f32, cam_pitch: f32) -> glam::Mat4 {
    let (y, p) = match mode {
        1 => (cam_yaw - 180.0, pitch),
        2 => (yaw, -cam_pitch),
        3 => (cam_yaw - 180.0, -cam_pitch),
        _ => (yaw, pitch),
    };
    glam::Mat4::from_rotation_y((-y).to_radians()) * glam::Mat4::from_rotation_x(p.to_radians())
}

// Die beiden Feuer-Texturen, im Wechsel uebereinander (ModelBaker.FIRE_0/FIRE_1).
const ENTITY_FIRE_TEXTURES: [&str; 2] = ["block/fire_0", "block/fire_1"];

// ItemEntity.uniqueOffset: in Vanilla zufaellig 0..2pi je Entity. Hier aus der Id gemischt
// (splitmix), damit derselbe Stapel in jedem Frame gleich wippt und dreht.
fn item_unique_offset(id: i32) -> f32 {
    let mut z = (id as u32 as u64).wrapping_add(0x9E37_79B9_7F4A_7C15);
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^= z >> 31;
    (z >> 40) as f32 / (1u64 << 24) as f32 * std::f32::consts::TAU
}

// ItemStackEntityRenderState.getRenderedAmount: wie viele Kopien ein Stapel zeigt.
fn dropped_item_rendered_amount(count: i32) -> usize {
    match count {
        ..=1 => 1,
        2..=16 => 2,
        17..=32 => 3,
        33..=48 => 4,
        _ => 5,
    }
}

// Javas LCG (CheckedRandom), mit dem ItemEntityRenderer die Kopien verstreut -- derselbe
// Seed ergibt dieselben Positionen wie in Vanilla.
struct JavaRandom(u64);

impl JavaRandom {
    const MUL: u64 = 0x5_DEEC_E66D;
    const MASK: u64 = (1 << 48) - 1;

    fn new(seed: i64) -> Self {
        Self((seed as u64 ^ Self::MUL) & Self::MASK)
    }

    fn next_float(&mut self) -> f32 {
        self.0 = (self.0.wrapping_mul(Self::MUL).wrapping_add(0xB)) & Self::MASK;
        (self.0 >> (48 - 24)) as f32 / (1u32 << 24) as f32
    }
}

// Die Versaetze der Kopien eines liegenden Stapels (ItemEntityRenderer.render), relativ zur
// gedrehten Grundlage. `tiefe` ist die z-Ausdehnung der Modellbox: flache Items (bis 1/16)
// stehen hintereinander wie ein Stapel Karten, dicke (Bloecke) liegen zufaellig im Umkreis
// von 0.15 verstreut.
fn dropped_item_copies(count: i32, seed: i32, tiefe: f32) -> Vec<world::entity_model::Affine> {
    use world::entity_model::Affine;
    let n = dropped_item_rendered_amount(count);
    let mut rng = JavaRandom::new(seed as i64);
    let mut streu = |faktor: f32| (rng.next_float() * 2.0 - 1.0) * 0.15 * faktor;
    let mut out = Vec::with_capacity(n);
    if tiefe > 0.0625 {
        out.push(Affine::IDENTITY);
        for _ in 1..n {
            let (x, y, z) = (streu(1.0), streu(1.0), streu(1.0));
            out.push(Affine::translation([x, y, z]));
        }
    } else {
        let schritt = tiefe * 1.5;
        let mut z = -(schritt * (n - 1) as f32 / 2.0);
        out.push(Affine::translation([0.0, 0.0, z]));
        z += schritt;
        for _ in 1..n {
            let (x, y) = (streu(0.5), streu(0.5));
            out.push(Affine::translation([x, y, z]));
            z += schritt;
        }
    }
    out
}

// Die Pfeiltextur fuer einen Entitytyp, oder None wenn es kein Pfeil ist. Der Dreizack hat
// ein eigenes Modell (ein Gegenstand, kein Kreuz) und steht deshalb NICHT hier.
fn arrow_texture(entity_type: i32) -> Option<&'static str> {
    match world::entity_type_name(entity_type)? {
        "arrow" => Some(world::entity_model::ARROW_TEXTURE),
        "spectral_arrow" => Some(world::entity_model::SPECTRAL_ARROW_TEXTURE),
        _ => None,
    }
}

// glam-Matrix (Spalten) -> world::entity_model::Affine (Zeilen: m[zeile][spalte]).
fn affine_from_mat4(m: glam::Mat4) -> world::entity_model::Affine {
    let c = |i: usize| m.col(i);
    world::entity_model::Affine {
        m: [[c(0).x, c(1).x, c(2).x], [c(0).y, c(1).y, c(2).y], [c(0).z, c(1).z, c(2).z]],
        t: [c(3).x, c(3).y, c(3).z],
    }
}

// Die Umkehrung von affine_from_mat4.
fn mat4_from_affine(a: &world::entity_model::Affine) -> glam::Mat4 {
    let m = &a.m;
    glam::Mat4::from_cols(
        glam::Vec4::new(m[0][0], m[1][0], m[2][0], 0.0),
        glam::Vec4::new(m[0][1], m[1][1], m[2][1], 0.0),
        glam::Vec4::new(m[0][2], m[1][2], m[2][2], 0.0),
        glam::Vec4::new(a.t[0], a.t[1], a.t[2], 1.0),
    )
}

// DyeColor.getSignColor je Farbindex -- die Schriftfarben auf Schildern.
const SIGN_TEXT_COLORS: [u32; 16] = [
    0xFFFFFF, 0xFF681F, 0xFF00FF, 0x9AC0CD, 0xFFFF00, 0xBFFF00, 0xFF69B4, 0x808080, 0xD3D3D3, 0x00FFFF, 0xA020F0, 0x0000FF, 0x8B4513, 0x00FF00,
    0xFF0000, 0x000000,
];

// AbstractSignBlockEntityRenderer.getTextColor: leuchtende Schrift in voller Farbe (Schwarz
// wird dabei zu 0xF0EBCC), sonst auf 40 % abgedunkelt.
// Blockecke relativ zum Auge, in f64 gerechnet und erst dann verkuerzt (s. ColumnOrigin).
fn block_rel(pos: (i32, i32, i32), eye: DVec3) -> [f32; 3] {
    let v = (DVec3::new(pos.0 as f64, pos.1 as f64, pos.2 as f64) - eye).as_vec3();
    [v.x, v.y, v.z]
}

fn sign_text_color(color: u8, glowing: bool) -> u32 {
    let c = SIGN_TEXT_COLORS[(color as usize).min(15)];
    if glowing {
        return if c == 0 { 0xF0EBCC } else { c };
    }
    let d = |v: u32| ((v as f32 * 0.4) as u32).min(255);
    (d((c >> 16) & 0xff) << 16) | (d((c >> 8) & 0xff) << 8) | d(c & 0xff)
}

// Offener Schild-Editor.
struct SignEdit {
    pos: (i32, i32, i32),
    front: bool,
    lines: [String; 4],
    row: usize,
    // Haengeschild: schmaleres Brett, 60 statt 90 Schriftpixel je Zeile.
    hanging: bool,
    wood: usize,
    color: u8,
    opened: Instant,
    // Schreibcursor auf dem Schild in der Welt, in Textkoordinaten des Bretts (s. sign_caret).
    caret: std::cell::Cell<Option<SignCaret>>,
}

// Gleitet wie CaretAnim (CARET_GLIDE, Easing.Out), aber auch zwischen den Zeilen.
#[derive(Clone, Copy)]
struct SignCaret {
    from: (f32, f32),
    to: (f32, f32),
    start: Instant,
}

impl SignCaret {
    fn at(&self, jetzt: Instant) -> (f32, f32) {
        let k = ease_out(jetzt.duration_since(self.start).as_secs_f32() / CARET_GLIDE.as_secs_f32());
        (self.from.0 + (self.to.0 - self.from.0) * k, self.from.1 + (self.to.1 - self.from.1) * k)
    }
}

// Punkt der Schild-Textebene (Schriftpixel) auf den Bildschirm; None hinter der Kamera.
fn sign_projector(clip: glam::Mat4, screen: (f32, f32)) -> impl Fn(f32, f32) -> Option<(f32, f32)> {
    let (sw, sh) = screen;
    move |x, y| {
        let c = clip * glam::Vec4::new(x, y, 0.0, 1.0);
        (c.w > NAMETAG_MIN_CLIP_W).then(|| ((c.x / c.w * 0.5 + 0.5) * sw, (0.5 - c.y / c.w * 0.5) * sh))
    }
}

// AffineTransformation.getMatrix: translation * left_rotation * scale * right_rotation.
fn display_affine_matrix(d: &world::DisplayTransform) -> glam::Mat4 {
    glam::Mat4::from_translation(glam::Vec3::from(d.translation))
        * joml_quat_matrix(d.left_rotation)
        * glam::Mat4::from_scale(glam::Vec3::from(d.scale))
        * joml_quat_matrix(d.right_rotation)
}

// TextDisplayEntityRenderer.render: rotate(PI um Y) * scale(-0.025) -- zusammen
// diag(0.025, -0.025, 0.025) -- dann translate(1 - m/2, -n, 0). Danach sind die Einheiten
// Schriftpixel, x nach rechts, y nach unten, Ursprung oben links an der ersten Zeile.
fn display_text_frame(m: f32, n: f32) -> glam::Mat4 {
    glam::Mat4::from_scale(glam::Vec3::new(WORLD_LABEL_WORLD_SCALE, -WORLD_LABEL_WORLD_SCALE, WORLD_LABEL_WORLD_SCALE))
        * glam::Mat4::from_translation(glam::Vec3::new(1.0 - m / 2.0, -n, 0.0))
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum LabelAlign {
    Center,
    Left,
    Right,
}

impl LabelAlign {
    // TextDisplayEntity.getAlignment: sind BEIDE Bits gesetzt, gilt CENTER.
    fn from_flags(flags: u8) -> Self {
        let links = flags & protocol::packets::TEXT_DISPLAY_FLAG_ALIGN_LEFT != 0;
        let rechts = flags & protocol::packets::TEXT_DISPLAY_FLAG_ALIGN_RIGHT != 0;
        match (links, rechts) {
            (true, false) => LabelAlign::Left,
            (false, true) => LabelAlign::Right,
            _ => LabelAlign::Center,
        }
    }
}

// Abschnitte an ihren Zeilenumbruechen in Zeilen zerlegen. Ein Umbruch mitten in einem
// Abschnitt teilt ihn, die Farbe laeuft in der neuen Zeile weiter.
fn split_label_lines(spans: &[protocol::nbt::TextSpan]) -> Vec<Vec<protocol::nbt::TextSpan>> {
    let mut lines = split_lines_vanilla(spans);
    // Leere Zeilen am Ende wegwerfen -- ein abschliessendes "\n" soll keinen leeren Streifen
    // Hintergrund erzeugen. Leere Zeilen MITTENDRIN bleiben: sie sind gesetzter Abstand.
    while lines.last().is_some_and(|l| l.is_empty()) {
        lines.pop();
    }
    lines
}

// Wie Vanillas StringSplitter: jedes "\n" beginnt eine Zeile, auch am Ende. Die Spielerliste
// braucht das -- Server schaffen mit leeren Zeilen nach einem hohen Logo-Zeichen im Kopf den
// Platz darunter; ohne sie lagen die Namen im Logo.
fn split_lines_vanilla(spans: &[protocol::nbt::TextSpan]) -> Vec<Vec<protocol::nbt::TextSpan>> {
    let mut lines = vec![Vec::new()];
    for span in spans {
        for (i, teil) in span.text.split('\n').enumerate() {
            if i > 0 {
                lines.push(Vec::new());
            }
            if !teil.is_empty() {
                lines.last_mut().expect("lines ist nie leer").push(protocol::nbt::TextSpan { text: teil.to_string(), color: span.color, link: span.link.clone(), action: span.action.clone(), style: span.style, shadow: span.shadow });
            }
        }
    }
    lines
}

// Zeilen auf `max_width` Schriftpixel umbrechen (TextDisplayEntity.LINE_WIDTH). Umgebrochen
// wird an Leerzeichen; ein einzelnes Wort, das allein schon zu breit ist, bleibt stehen und
// ragt heraus -- genau wie in Vanilla, wo TextRenderer.wrapLines es ebenfalls nicht
// zerschneidet.
fn wrap_label_lines(
    lines: &[Vec<protocol::nbt::TextSpan>],
    max_width: f32,
    measure: impl Fn(&str) -> f32,
) -> Vec<Vec<protocol::nbt::TextSpan>> {
    if !max_width.is_finite() {
        return lines.to_vec();
    }
    let mut out: Vec<Vec<protocol::nbt::TextSpan>> = Vec::with_capacity(lines.len());
    for line in lines {
        let mut aktuell: Vec<protocol::nbt::TextSpan> = Vec::new();
        let mut breite = 0.0f32;
        for span in line {
            // Die Trennstellen mitfuehren, damit das Leerzeichen am Zeilenende verschwindet,
            // mitten in der Zeile aber erhalten bleibt.
            for (i, wort) in span.text.split(' ').enumerate() {
                let mit_luecke = if i > 0 && !aktuell.is_empty() { format!(" {wort}") } else { wort.to_string() };
                if mit_luecke.is_empty() {
                    continue;
                }
                let w = measure(&mit_luecke);
                if breite > 0.0 && breite + w > max_width {
                    out.push(std::mem::take(&mut aktuell));
                    breite = 0.0;
                    let nackt = wort.to_string();
                    breite += measure(&nackt);
                    aktuell.push(protocol::nbt::TextSpan { text: nackt, color: span.color, link: span.link.clone(), action: span.action.clone(), style: span.style, shadow: span.shadow });
                    continue;
                }
                breite += w;
                match aktuell.last_mut() {
                    Some(last) if last.color == span.color && last.link == span.link && last.action == span.action => last.text.push_str(&mit_luecke),
                    _ => aktuell.push(protocol::nbt::TextSpan { text: mit_luecke, color: span.color, link: span.link.clone(), action: span.action.clone(), style: span.style, shadow: span.shadow }),
                }
            }
        }
        out.push(aktuell);
    }
    out
}

// Eine gezeichnete Textzeile: ihr senkrechter Streifen und je Zeichen der waagerechte
// Bereich [von, bis) in Bildschirmpixeln (s. GpuState::shape_text).
#[derive(Clone, Debug, Default)]
struct TextRun {
    top: f32,
    bottom: f32,
    glyphs: Vec<(char, f32, f32)>,
    // Auswahlbereich (s. selection_boundary): eine Auswahl bleibt in dem Bereich, in dem sie
    // begonnen hat.
    group: u32,
}

// Was unter einer Stelle des offenen Chats liegt: ein Link und/oder die uebrigen Aktionen
// des Abschnitts (Klick, Tooltip, Shift-Einfuegen, s. nbt::SpanAction).
#[derive(Clone)]
struct ChatHit {
    link: Option<String>,
    action: Option<std::sync::Arc<protocol::nbt::SpanAction>>,
}

// Der UI-Pass zeichnet ALLE Flaechen vor ALLEM Text (s. render_world) -- ein Tooltip-Kasten
// ueber dem Chat laege also unter dessen Schrift. Deshalb wird der Chattext ab `from` unter
// `cover` ausgespart: von jedem Stueck, das hineinragt, bleibt nur, was links und rechts
// daneben steht. Flaechen ab `rects_from` (Unterstreichungen, Eingabefeld, Listen) bekommen
// ein Loch in Kastengroesse: bis zu vier Stuecke drumherum.
fn cut_ui_under(gpu: &GpuState, texts: &mut Vec<UiText>, from: usize, rects: &mut Vec<UiRect>, rects_from: usize, cover: Rect) {
    let rechts = cover.x + cover.w;
    let unten = cover.y + cover.h;
    let mut neu = Vec::with_capacity(texts.len());
    for (i, t) in texts.drain(..).enumerate() {
        let w = gpu.measure_text(&t.text, t.scale);
        let h = gpu.text_height(t.scale);
        let trifft = i >= from && !is_selection_boundary(&t) && t.y < unten && t.y + h > cover.y && t.x < rechts && t.x + w > cover.x;
        if !trifft {
            neu.push(t);
            continue;
        }
        // Zeichenweise: was vor dem Kasten endet, bleibt links stehen; was nach ihm anfaengt,
        // rechts -- an seiner alten Stelle.
        let mut links = String::new();
        let mut rest: Option<(String, f32)> = None;
        let mut x = t.x;
        for c in t.text.chars() {
            let cw = gpu.measure_text(c.encode_utf8(&mut [0u8; 4]), t.scale);
            if x + cw <= cover.x {
                links.push(c);
            } else if x >= rechts {
                rest.get_or_insert_with(|| (String::new(), x)).0.push(c);
            }
            x += cw;
        }
        if !links.is_empty() {
            neu.push(UiText { text: links, x: t.x, y: t.y, color: t.color, scale: t.scale });
        }
        if let Some((text, x)) = rest {
            neu.push(UiText { text, x: x.round(), ..t });
        }
    }
    *texts = neu;
    let mut flaechen = Vec::with_capacity(rects.len());
    for (i, r) in rects.drain(..).enumerate() {
        let Rect { x, y, w, h } = r.rect;
        if i < rects_from || y >= unten || y + h <= cover.y || x >= rechts || x + w <= cover.x {
            flaechen.push(r);
            continue;
        }
        // Oben und unten ueber die volle Breite, links und rechts nur im Band des Kastens.
        let band_oben = y.max(cover.y);
        let band_unten = (y + h).min(unten);
        let stuecke = [
            Rect { x, y, w, h: cover.y - y },
            Rect { x, y: unten, w, h: y + h - unten },
            Rect { x, y: band_oben, w: cover.x - x, h: band_unten - band_oben },
            Rect { x: rechts, y: band_oben, w: x + w - rechts, h: band_unten - band_oben },
        ];
        for rect in stuecke.into_iter().filter(|r| r.w > 0.0 && r.h > 0.0) {
            flaechen.push(UiRect { rect, color: r.color, ..UiRect::FLAT });
        }
    }
    *rects = flaechen;
}

// TridentItem.onStoppedUsing: unter 10 Ticks Benutzung passiert beim Loslassen nichts.
const TRIDENT_MIN_USE_TICKS: u32 = 10;
// Haltbarkeit des Dreizacks, wenn der Stack keine eigene nennt (items.json: max_damage 250).
const TRIDENT_MAX_DAMAGE: i32 = 250;

// No Tool Break: nur Diamant- und Netherit-Werkzeuge, mit der Standard-Haltbarkeit ihrer Stufe.
fn protected_tool_durability(name: &str) -> Option<i32> {
    let (stufe, art) = name.split_once('_')?;
    if !matches!(art, "pickaxe" | "axe" | "shovel" | "hoe" | "sword") {
        return None;
    }
    match stufe {
        "diamond" => Some(DIAMOND_TOOL_DURABILITY),
        "netherite" => Some(NETHERITE_TOOL_DURABILITY),
        _ => None,
    }
}

// Vanillas Standard-Haltbarkeit (max_damage-Komponente) je Item -- der Server schickt
// max_damage nur mit, wenn er vom Standard abweicht. None = das Item hat keine Haltbarkeit.
// Werkzeuge nach Material (ToolMaterial), Ruestung nach Material mal Teil (ArmorMaterial:
// Helm 11, Brust 16, Hose 15, Stiefel 13).
fn default_max_damage(name: &str) -> Option<i32> {
    let fest = match name {
        "bow" => 384,
        "crossbow" => 465,
        "trident" => 250,
        "shield" => 336,
        "elytra" => 432,
        "mace" => 500,
        "fishing_rod" | "flint_and_steel" | "brush" | "wolf_armor" => 64,
        "shears" => 238,
        "carrot_on_a_stick" => 25,
        "warped_fungus_on_a_stick" => 100,
        "turtle_helmet" => 275,
        _ => 0,
    };
    if fest > 0 {
        return Some(fest);
    }
    let (stufe, art) = name.split_once('_')?;
    let werkzeug = match stufe {
        "wooden" => Some(59),
        "stone" => Some(131),
        "copper" => Some(190),
        "iron" => Some(250),
        "golden" => Some(32),
        "diamond" => Some(1561),
        "netherite" => Some(2031),
        _ => None,
    };
    if matches!(art, "pickaxe" | "axe" | "shovel" | "hoe" | "sword" | "spear") {
        return werkzeug;
    }
    let teil = match art {
        "helmet" => 11,
        "chestplate" => 16,
        "leggings" => 15,
        "boots" => 13,
        _ => return None,
    };
    let material = match stufe {
        "leather" => 5,
        "copper" => 11,
        "chainmail" | "iron" => 15,
        "golden" => 7,
        "diamond" => 33,
        "netherite" => 37,
        _ => return None,
    };
    Some(teil * material)
}

// Vanillas Haltbarkeitsbalken (ItemStack.getItemBarStep/-Color): Breite in 16tel-Slot-Pixeln
// (0..13) und Farbe von Gruen ueber Gelb nach Rot. None, solange das Item unbeschaedigt ist.
// Braucht ein Item einen Tooltip, um erkannt zu werden? Ja, wenn etwas daran haengt, das
// das Symbol nicht zeigt: Verzauberungen (auch gespeicherte), ein eigener Name oder
// Server-Itemname, Lore, ein Trank, ein Ruestungsbesatz, Bannermuster, ein Kopf mit Profil
// oder ein anderes Modell. Ein gewoehnlicher Schneeball, Stein oder ein Diamantschwert ohne
// Verzauberung braucht keinen -- Haltbarkeit zeigt der Balken.
fn item_needs_tooltip(stack: &protocol::item::ItemStack) -> bool {
    !stack.enchantments.is_empty()
        || !stack.stored_enchantments.is_empty()
        || stack.custom_name.is_some()
        || stack.item_name_spans.is_some()
        || !stack.lore.is_empty()
        || stack.potion.is_some()
        || stack.trim.is_some()
        || !stack.banner_patterns.is_empty()
        || stack.profile.is_some()
        || stack.item_model.is_some()
        || world::bundle::is_bundle(stack)
        || stack.written_book.is_some()
}

// Wert eines Attributs, das ein Item anlegt, ausgehend von `basis` (dem Grundwert des
// Spielers): erst alle add_value, dann add_multiplied_base auf diese Summe, dann je
// add_multiplied_total mal (1 + Betrag) -- wie AttributeInstance.calculateValue. None, wenn
// das Item das Attribut in diesen Slots gar nicht anfasst.
fn item_attribute_value(mods: &[protocol::item::ItemAttributeModifier], attribute: i32, basis: f64, slot: &dyn Fn(i32) -> bool) -> Option<f64> {
    let passend: Vec<_> = mods.iter().filter(|m| m.attribute == attribute && slot(m.slot)).collect();
    if passend.is_empty() {
        return None;
    }
    let summe = basis + passend.iter().filter(|m| m.operation == 0).map(|m| m.amount).sum::<f64>();
    let mut wert = summe + passend.iter().filter(|m| m.operation == 1).map(|m| summe * m.amount).sum::<f64>();
    for m in passend.iter().filter(|m| m.operation == 2) {
        wert *= 1.0 + m.amount;
    }
    Some(wert)
}

// Zahl mit hoechstens einer Nachkommastelle und deutschem Komma, ohne ",0".
fn decimal_de(v: f64) -> String {
    let gerundet = (v * 10.0).round() / 10.0;
    if gerundet.fract() == 0.0 {
        format!("{}", gerundet as i64)
    } else {
        format!("{gerundet:.1}").replace('.', ",")
    }
}

// So viele Ticks nach dem lokalen Fertigessen wartet der naechste Bissen (s. tick_item_use).
const EAT_NEXT_USE_DELAY: u32 = 1;

// Fehlen nach `benutzt` von `dauer` Ticks hoechstens `grenze_ms` Millisekunden? Ein Tick sind
// 50 ms; schon fertig zaehlt als "nichts fehlt".
fn eat_rest_within(dauer: u32, benutzt: u32, grenze_ms: u32) -> bool {
    dauer.saturating_sub(benutzt) * 50 <= grenze_ms
}

// Hoechsthaltbarkeit eines Stapels, None ohne Haltbarkeit (oder unzerbrechlich, dann zeigt
// Vanilla keinen Balken): die wirksame max_damage-Component, ohne Standards die Tabelle.
fn max_damage_of(stack: &protocol::item::ItemStack, name: &str) -> Option<i32> {
    if world::item_components::loaded() {
        return world::item_behavior::damageable(stack).then(|| world::item_components::Components::of(stack).max_damage());
    }
    stack.max_damage.or_else(|| default_max_damage(name))
}

// Verbleibende Haltbarkeit 0..1, None fuer Items ohne Haltbarkeit.
fn durability_rest(stack: &protocol::item::ItemStack, name: &str) -> Option<f32> {
    let max = max_damage_of(stack, name)?;
    (max > 0).then(|| ((max - stack.damage.unwrap_or(0)) as f32 / max as f32).clamp(0.0, 1.0))
}

// Verbleibende Haltbarkeitspunkte, None fuer Items ohne Haltbarkeit.
fn durability_points(stack: &protocol::item::ItemStack, name: &str) -> Option<i32> {
    let max = max_damage_of(stack, name)?;
    (max > 0).then(|| (max - stack.damage.unwrap_or(0)).max(0))
}

fn item_bar(stack: &protocol::item::ItemStack, name: &str) -> Option<(f32, [f32; 3])> {
    let damage = stack.damage.unwrap_or(0);
    let max = max_damage_of(stack, name)?;
    if damage <= 0 || max <= 0 {
        return None;
    }
    let schritt = (13.0 - damage as f32 * 13.0 / max as f32).round().clamp(0.0, 13.0);
    let rest = ((max - damage) as f32 / max as f32).max(0.0);
    // MathHelper.hsvToRgb(f / 3, 1, 1): Ton 0 (rot) bis 1/3 (gruen).
    let ton = rest / 3.0 * 6.0;
    let x = 1.0 - (ton % 2.0 - 1.0).abs();
    let farbe = if ton < 1.0 { [1.0, x, 0.0] } else { [x, 1.0, 0.0] };
    Some((schritt, farbe))
}

// Fuer die Benachrichtigung: ein umbenanntes Werkzeug unter seinem Namen, sonst lesbar.
fn tool_display_name(stack: &protocol::item::ItemStack, name: &str) -> String {
    if let Some(eigen) = &stack.custom_name {
        return eigen.clone();
    }
    let (stufe, art) = name.split_once('_').unwrap_or(("", name));
    let stufe = match stufe {
        "diamond" => "Diamant",
        "netherite" => "Netherit",
        s => s,
    };
    let art = match art {
        "pickaxe" => "spitzhacke",
        "axe" => "axt",
        "shovel" => "schaufel",
        "hoe" => "hacke",
        "sword" => "schwert",
        a => a,
    };
    format!("{stufe}{art}")
}

// ItemStack.willBreakNextUse: beschaedigbar und nur noch ein Punkt Haltbarkeit uebrig. Nur fuer
// den Dreizack gebraucht -- ohne Standards ist dessen Haltbarkeit deshalb der Rueckfall.
fn will_break_next_use(stack: &protocol::item::ItemStack) -> bool {
    if world::item_components::loaded() {
        return world::item_behavior::next_damage_will_break(stack);
    }
    stack.damage.unwrap_or(0) >= stack.max_damage.unwrap_or(TRIDENT_MAX_DAMAGE) - 1
}

// CrossbowPullProperty: Benutzungsdauer durch Ladezeit. Bei Ladezeit 0 (Schnellladen V per
// Befehl) teilt Vanilla durch null und landet bei +Unendlich -- sofort voll gespannt.
// Consumable.shouldEmitParticlesAndSounds: Kruemel erst nach gut einem Fuenftel der Essdauer,
// dann alle vier Ticks. `ticks` zaehlt den laufenden Tick mit (1 im ersten Tick); die Restzeit
// darf negativ werden -- bei anderen Spielern isst es weiter, bis der Server Schluss sagt.
fn eating_crumbs_due(dauer: u32, ticks: u32) -> bool {
    let benutzt = ticks as i64 - 1;
    let rest = dauer as i64 - benutzt;
    benutzt > (dauer as f32 * 0.21875) as i64 && rest.rem_euclid(4) == 0
}

#[cfg(test)]
mod kruemel_tests {
    // Brot (32 Ticks): die ersten sieben Ticks nichts, dann alle vier Ticks -- und nach Ablauf
    // der Dauer weiter im selben Takt.
    #[test]
    fn kruemel_nach_einem_fuenftel_alle_vier_ticks() {
        let ticks: Vec<u32> = (1..=45).filter(|&t| super::eating_crumbs_due(32, t)).collect();
        assert_eq!(ticks, vec![9, 13, 17, 21, 25, 29, 33, 37, 41, 45]);
    }
}

// Welches Item ein Item-Partikel zeigt: das Modell (item_model), wenn es ein Vanilla-Item
// ist -- ein Packmodell hat keinen Platz im Partikel-Atlas, dann das Item selbst.
fn particle_item_name(h: &world::HeldItem) -> Option<&'static str> {
    let id = if h.model_id < world::entity::CUSTOM_MODEL_BASE { h.model_id } else { h.item_id };
    world::item_registry::item_name(id)
}

fn crossbow_pull_progress(use_ticks: f32, pull_ticks: f32) -> f32 {
    if pull_ticks <= 0.0 {
        f32::INFINITY
    } else {
        use_ticks / pull_ticks
    }
}

// Der Tempo-Faktor aus use_effects (f32) fuer die f64-Physik: als die Dezimalzahl, die er
// darstellt (0.2, nicht 0.20000000298...) -- so rechnete die Bewegung schon vorher, und so
// bleibt sie Bit fuer Bit dieselbe.
fn use_speed_f64(m: f32) -> f64 {
    m.to_string().parse().unwrap_or(m as f64)
}

// Ein Kartenbild als Viereck 0..128 in x/y (MapRenderer: y nach unten = v nach unten), unter
// `m` in die Welt gesetzt.
fn push_map_quad(m: world::entity_model::Affine, [u0, v0, u1, v1]: [f32; 4], hell: f32, out: &mut Vec<world::BlockVertex>) {
    let ecke = |x: f32, y: f32, u: f32, v: f32| world::BlockVertex { position: m.apply([x, y, -0.01]), color: [hell; 3], uv: [u, v] };
    let (a, b, c, d) = (ecke(0.0, 128.0, u0, v1), ecke(128.0, 128.0, u1, v1), ecke(128.0, 0.0, u1, v0), ecke(0.0, 0.0, u0, v0));
    out.extend([a, b, c, a, c, d]);
}

// ItemInHandRenderer.calculateMapTilt: je weiter man nach unten schaut, desto flacher liegt die
// Karte (0 beim Geradeausblick bis 1 ab etwa 50 Grad nach unten), weich ueber einen Kosinus.
fn map_tilt(pitch_deg: f32) -> f32 {
    let t = (1.0 - pitch_deg / 45.0 + 0.1).clamp(0.0, 1.0);
    -(t * std::f32::consts::PI).cos() * 0.5 + 0.5
}

// Ein belegter Kartenplatz im Entity-Atlas (s. App::ensure_map_textures).
#[derive(Clone, Copy)]
struct MapSlot {
    id: i32,
    im_rahmen: bool,
    revision: u32,
    zuletzt: u64,
}

// Breite des Buendel-Tooltips in GUI-Pixeln (ClientBundleTooltip).
const BUNDLE_PANEL_W: f32 = 96.0;

// Bis zu so vielen Zweigen werden alle Modelle einer Definition in der eigenen Hand vorgeladen
// (s. prepare_held_items).
const HAND_MODEL_PRELOAD_MAX: usize = 8;

// Welche Item-Definition (items/<id>.json) einen Stapel zeichnet: die item_model-Component
// ("minecraft:mace" -> "mace", "uhc:storm_wall" bleibt), sonst der Itemname.
fn model_definition_id(stack: &protocol::item::ItemStack, name: &str) -> String {
    match stack.item_model.as_deref() {
        Some(m) => m.strip_prefix("minecraft:").unwrap_or(m).to_string(),
        None => name.to_string(),
    }
}

// Welches Icon ein Stack bekommt. Meist der Itemname; die geladene Armbrust zeigt wie in
// Vanilla (items/crossbow.json, select auf charge_type) den Pfeil bzw. die Rakete.
fn item_icon_name<'a>(name: &'a str, stack: &protocol::item::ItemStack) -> &'a str {
    if name == "crossbow" && stack.is_charged() {
        let rakete = world::item_registry::item_id_by_name("firework_rocket");
        return if stack.charged_projectiles.iter().any(|id| Some(*id) == rakete) { "crossbow_firework" } else { "crossbow_arrow" };
    }
    name
}

// Grenze zwischen zwei Auswahlbereichen im Textstrom -- z.B. zwischen Log und Serverliste
// oder zwischen Chatverlauf, Eingabe und Liste der gesendeten Nachrichten. Ohne Grenze nahm
// eine Auswahl ueber zwei Listen hinweg Text aus beiden mit. Technisch ein leerer
// Text mit negativem Alpha, den shape_text als Bereichswechsel liest und nicht zeichnet.
fn selection_boundary(texts: &mut Vec<UiText>) {
    texts.push(UiText { text: String::new(), x: 0.0, y: 0.0, color: [0.0, 0.0, 0.0, -1.0], scale: 1.0 });
}

fn is_selection_boundary(t: &UiText) -> bool {
    t.text.is_empty() && t.color[3] == -1.0
}

// Marker in der Textliste: ab hier gilt fuer die folgenden Texte dieser Rand (None = zurueck
// zur allgemeinen Einstellung). Wie selection_boundary ein leerer Text mit negativem Alpha,
// den shape_text liest und nicht zeichnet -- so muss nicht jeder UiText ein eigenes Feld
// tragen.
fn push_shadow_marker(texts: &mut Vec<UiText>, stil: Option<(TextShadow, f32)>) {
    // Die Staerke (s. Settings::shadow_strength) reist im x des Markers mit.
    let staerke = stil.map_or(0.0, |(_, s)| s);
    let code = match stil.map(|(s, _)| s) {
        None => -2.0,
        Some(TextShadow::Outline) => -3.0,
        Some(TextShadow::Vanilla) => -4.0,
        Some(TextShadow::Off) => -5.0,
        Some(TextShadow::Below) => -30.0,
        Some(TextShadow::Around) => -31.0,
    };
    texts.push(UiText { text: String::new(), x: staerke, y: 0.0, color: [0.0, 0.0, 0.0, code], scale: 1.0 });
}

// Some(neuer Stil) fuer einen Marker aus push_shadow_marker, sonst None.
fn shadow_marker(t: &UiText) -> Option<Option<(TextShadow, f32)>> {
    if !t.text.is_empty() {
        return None;
    }
    let stil = match t.color[3] {
        -2.0 => return Some(None),
        -3.0 => TextShadow::Outline,
        -4.0 => TextShadow::Vanilla,
        -5.0 => TextShadow::Off,
        -30.0 => TextShadow::Below,
        -31.0 => TextShadow::Around,
        _ => return None,
    };
    Some(Some((stil, t.x)))
}

// Schattenfarbe, die der Server einem Abschnitt gibt (TextSpan::shadow), fuer den GLEICH
// FOLGENDEN Text -- nur fuer ihn, damit nichts auf Nachbartext ueberlaeuft. Ohne eigene Farbe
// kein Marker. Code -6; rgb in color (linear), das Alpha des Servers in x.
fn push_span_shadow(texts: &mut Vec<UiText>, shadow: Option<u32>) {
    let Some(argb) = shadow else { return };
    let [r, g, b, _] = rgb_to_rgba(argb & 0xFF_FFFF);
    texts.push(UiText { text: String::new(), x: (argb >> 24) as f32 / 255.0, y: 0.0, color: [r, g, b, -6.0], scale: 1.0 });
}

// Der GLEICH FOLGENDE Text ist fett (Code -7): shape_text zeichnet ihn ein zweites Mal um
// einen Font-Pixel nach rechts (Vanillas boldOffset) und gibt jedem Zeichen diesen Pixel mehr
// Vorschub. Als EIN Text statt zwei, damit erst beide Raender und dann beide Glyphen kommen --
// sonst lag der Rand des zweiten Durchgangs mitten in den Buchstaben des ersten, und
// fett mit Kontur sah schlecht aus.
fn push_bold_marker(texts: &mut Vec<UiText>) {
    texts.push(UiText { text: String::new(), x: 0.0, y: 0.0, color: [0.0, 0.0, 0.0, -7.0], scale: 1.0 });
}

fn is_bold_marker(t: &UiText) -> bool {
    t.text.is_empty() && t.color[3] == -7.0
}

// Der GLEICH FOLGENDE Text ist Eingabe (Code -8): aus ihm lernt stable_numbers nichts. Wer
// tippt, aendert Zahlen staendig -- als "wechselnd" erkannt, behielte eine Zahl im Eingabefeld
// den Platz ihrer laengsten Fassung, und nach dem Loeschen klaffte eine Luecke. Gilt fuer
// jedes Feld, in das man schreibt: Chat, Buch, Schild, Amboss, Zahlen- und Namensfelder.
fn push_typed_marker(texts: &mut Vec<UiText>) {
    texts.push(UiText { text: String::new(), x: 0.0, y: 0.0, color: [0.0, 0.0, 0.0, -8.0], scale: 1.0 });
}

fn is_typed_marker(t: &UiText) -> bool {
    t.text.is_empty() && t.color[3] == -8.0
}

// Geloeschte Zeichen fallen heraus wie in osu! (osu-framework BasicTextBox,
// FallingDownContainer.Hide): ausblenden und dabei beschleunigt (InQuad) nach unten. Dazu
// jedes Zeichen fuer sich und etwas zufaellig (Wunsch des Nutzers): Fallweg, seitliche Drift
// und Drehung streuen je Zeichen, die Dauer auch (ERASE_FALL ist die laengste). Gilt fuer
// jedes Feld mit Eingabe-Markierung (s. push_typed_marker).
const ERASE_FALL: Duration = Duration::from_millis(320);

// Ein Stueck getippter Text, wie es gezeichnet wurde.
#[derive(Clone, Debug, PartialEq)]
struct TypedRun {
    text: String,
    x: f32,
    y: f32,
    scale: f32,
    color: [f32; 4],
    // Schrift und Rand des Bereichs, in dem er stand (s. begin_text_area) -- das Herausfallende
    // wird darin gemessen und gezeichnet, sonst laege es neben seiner alten Stelle.
    font: Option<FontKind>,
    shadow: Option<(TextShadow, f32)>,
}

// Ein herausfallendes Zeichen: Lage und Aussehen beim Loeschen, Breite und Hoehe (um die
// Mitte dreht es sich), dazu sein Zufall: Fallweg, Drift zur Seite, Drehung am Ende (rad) und
// Dauer.
struct FallingGlyph {
    run: TypedRun,
    w: f32,
    h: f32,
    fall: f32,
    drift: f32,
    angle: f32,
    dur: Duration,
    start: Instant,
}

impl FallingGlyph {
    // Zufall aus drei Werten in -1..1 (s. zufallswert).
    fn new(run: TypedRun, w: f32, h: f32, start: Instant, r: [f32; 4]) -> Self {
        FallingGlyph {
            run,
            w,
            h,
            fall: h * (1.3 + 0.5 * r[0]),
            drift: h * 0.35 * r[1],
            angle: 0.6 * r[2],
            dur: ERASE_FALL.mul_f32(0.8 + 0.2 * r[3]),
            start,
        }
    }

    // Stand nach `t` Sekunden: Text an seiner Stelle, Drehpunkt, Winkel. None = vorbei.
    fn at(&self, t: f32) -> Option<(UiText, (f32, f32), f32)> {
        let k = t / self.dur.as_secs_f32();
        if k >= 1.0 {
            return None;
        }
        let x = self.run.x + self.drift * k;
        let y = self.run.y + self.fall * k * k;
        let [r, g, b, a] = self.run.color;
        let text = UiText { text: self.run.text.clone(), x, y, color: [r, g, b, a * (1.0 - k)], scale: self.run.scale };
        Some((text, (x + self.w / 2.0, y + self.h / 2.0), self.angle * k))
    }
}

// Alle Eingabe-Texte eines Frames in Zeichenreihenfolge: je der Text direkt hinter einer
// Eingabe-Markierung.
fn typed_runs<'a>(texts: impl Iterator<Item = &'a UiText>) -> Vec<TypedRun> {
    let mut out = Vec::new();
    let mut nach_marker = false;
    let (mut font, mut shadow) = (None, None);
    for t in texts {
        if is_typed_marker(t) {
            nach_marker = true;
            continue;
        }
        if let Some(f) = font_marker(t) {
            font = f;
            continue;
        }
        if let Some(s) = shadow_marker(t) {
            shadow = s;
            continue;
        }
        if nach_marker && !t.text.is_empty() {
            out.push(TypedRun { text: t.text.clone(), x: t.x, y: t.y, scale: t.scale, color: t.color, font, shadow });
        }
        nach_marker = false;
    }
    out
}

// Was zwischen zwei Frames aus dem getippten Text verschwunden ist, an seiner ALTEN Stelle:
// gemeinsamer Anfang und gemeinsames Ende bleiben, der Rest des alten Texts ist geloescht.
// `breite` misst Text in Pixeln, so wie er in diesem Stueck steht (Schrift, Skalierung).
//
// `caret` = wo der Cursor im alten Frame stand. Er entscheidet zweierlei:
//   - WELCHE Zeichen weg sind, wenn der Text das offenlaesst: aus "asdasdasd" wird durch
//     Loeschen jedes "asd" dasselbe "asdasd". Geloescht wird immer am Cursor (Ruecktaste
//     davor, Entf dahinter, eine Markierung reicht an ihn heran), also die Stelle dort.
//   - WO sie losfallen: ein Stueck, das am Cursor sass, faellt buendig an ihm. Im Chat gleitet
//     der Text links vom Cursor nach jedem Loeschen noch kurz (s. ChatSlide); wer schnell
//     loescht, faende die Zeichen sonst dort, wo der Text gerade hinglitt, vor dem Cursor.
//
// `genau` = was das Feld selbst gemeldet hat (s. chat_input::Erased): Anfang im alten Text,
// Laenge und ob der Cursor daran stand. Passt es zum Text, gilt es statt jeder Vermutung --
// eine Mausmarkierung kann weit weg vom Cursor liegen, dort fiele sonst das Falsche.
fn erased_pieces(alt: &[TypedRun], neu: &[TypedRun], breite: impl Fn(&TypedRun, &str) -> f32, mut caret: Option<(f32, f32)>, genau: Option<(usize, usize, bool)>) -> Vec<TypedRun> {
    let a: String = alt.iter().map(|r| r.text.as_str()).collect();
    let b: String = neu.iter().map(|r| r.text.as_str()).collect();
    let anfang: usize = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).map(|(x, _)| x.len_utf8()).sum();
    let ende: usize = a[anfang..].chars().rev().zip(b[anfang..].chars().rev()).take_while(|(x, y)| x == y).map(|(x, _)| x.len_utf8()).sum();
    let (mut von, mut bis) = (anfang, a.len() - ende);
    // Ergibt alt ohne a[s..s+n] wieder neu?
    let passt = |s: usize, n: usize| a.len() == b.len() + n && a.is_char_boundary(s) && a.is_char_boundary(s + n) && a[..s] == b[..s] && a[s + n..] == b[s..];
    // Bildschirmstelle einer Byte-Position im alten Text: (x, y) des Zeichens dort bzw. des
    // Endes des letzten Stuecks.
    let stelle = |pos: usize, am_ende: bool| -> Option<(f32, f32)> {
        let mut offset = 0;
        for r in alt {
            let (s, e) = (offset, offset + r.text.len());
            offset = e;
            if (s <= pos && pos < e) || (am_ende && s < pos && pos <= e) {
                return Some((r.x + breite(r, &r.text[..pos - s]), r.y));
            }
        }
        None
    };
    if let Some((s, n, am_cursor)) = genau.filter(|&(s, n, _)| passt(s, n)) {
        (von, bis) = (s, s + n);
        // Nur was am Cursor sass, rueckt an ihn heran.
        if !am_cursor {
            caret = None;
        }
    } else if let Some((cx, cy)) = caret.filter(|_| a.len() > b.len()) {
        // Reines Loeschen: jede Lage p, bei der alt ohne a[p..p+n] wieder neu ergibt, passt.
        // Davon die, deren Anfang oder Ende dem Cursor am naechsten liegt.
        let n = a.len() - b.len();
        let hinten: usize = a.chars().rev().zip(b.chars().rev()).take_while(|(x, y)| x == y).map(|(x, _)| x.len_utf8()).sum();
        let abstand = |p: usize| {
            [stelle(p, false), stelle(p + n, true)]
                .into_iter()
                .flatten()
                .map(|(x, y)| (x - cx).abs() + (y - cy).abs())
                .fold(f32::INFINITY, f32::min)
        };
        let erste = b.len().saturating_sub(hinten);
        let beste = (erste..=anfang.min(b.len())).filter(|&p| passt(p, n)).min_by(|&p, &q| abstand(p).total_cmp(&abstand(q)));
        if let Some(p) = beste {
            (von, bis) = (p, p + n);
        }
    }
    let mut out = Vec::new();
    let mut offset = 0;
    for r in alt {
        let (s, e) = (offset, offset + r.text.len());
        offset = e;
        let (lo, hi) = (von.max(s), bis.min(e));
        if lo >= hi {
            continue;
        }
        let (i, j) = (lo - s, hi - s);
        let mut stueck = TypedRun { text: r.text[i..j].to_string(), x: r.x + breite(r, &r.text[..i]), ..r.clone() };
        // Sass das Stueck in der Zeile des Cursors an ihm, buendig an ihn (s. oben).
        if let Some((cx, cy)) = caret {
            let w = breite(r, &stueck.text);
            let h = 8.0 * r.scale;
            let (vorn, hinten) = (cx - stueck.x, cx - (stueck.x + w));
            let schub = if hinten.abs() <= vorn.abs() { hinten } else { vorn };
            if (stueck.y - cy).abs() < h && schub.abs() < 4.0 * h {
                stueck.x += schub;
            }
        }
        out.push(stueck);
    }
    out
}

// Ab hier ruhiger Text (Code -33) bzw. wieder normaler (-34): Zahlen darin stehen in ihrer
// natuerlichen Breite und lehren stable_numbers nichts. Fuer den Chat -- eine Nachricht
// aendert sich nicht, reservierter Platz zerriss dort nur "(1 - 0)" oder "14/15", weil
// dasselbe Muster anderswo wechselte.
fn push_plain_numbers_marker(texts: &mut Vec<UiText>, an: bool) {
    texts.push(UiText { text: String::new(), x: 0.0, y: 0.0, color: [0.0, 0.0, 0.0, if an { -33.0 } else { -34.0 }], scale: 1.0 });
}

fn plain_numbers_marker(t: &UiText) -> Option<bool> {
    if !t.text.is_empty() {
        return None;
    }
    match t.color[3] {
        -33.0 => Some(true),
        -34.0 => Some(false),
        _ => None,
    }
}

// Die Schattenfarbe aus einem Marker von push_span_shadow (Alpha noch ohne die Textdeckkraft).
fn span_shadow_marker(t: &UiText) -> Option<[f32; 4]> {
    (t.text.is_empty() && t.color[3] == -6.0).then_some([t.color[0], t.color[1], t.color[2], t.x])
}

// Wie push_shadow_marker, fuer die Schrift: ab hier gilt fuer die folgenden Texte diese
// Schrift (None = zurueck zur allgemeinen). Codes -9 (allgemein) und -10 - FontKind-Index.
fn push_font_marker(texts: &mut Vec<UiText>, font: Option<FontKind>) {
    let code = font.map_or(-9.0, |k| -10.0 - FontKind::ALL.iter().position(|&f| f == k).unwrap_or(0) as f32);
    texts.push(UiText { text: String::new(), x: 0.0, y: 0.0, color: [0.0, 0.0, 0.0, code], scale: 1.0 });
}

// Some(neue Schrift) fuer einen Marker aus push_font_marker, sonst None.
fn font_marker(t: &UiText) -> Option<Option<FontKind>> {
    if !t.text.is_empty() {
        return None;
    }
    let c = t.color[3];
    if c == -9.0 {
        return Some(None);
    }
    let i = -10.0 - c;
    (i >= 0.0 && i.fract() == 0.0).then(|| FontKind::ALL.get(i as usize).copied()).flatten().map(Some)
}

// Das Rand-Viereck eines Glyphen (s. font.wgsl): bei der Kontur rundherum einen
// Bildschirmpixel groesser, beim Vanilla-Schatten um den Versatz nach rechts unten verlaengert.
// Die UV laufen im selben Mass ueber das Glyphenrechteck hinaus; was dort liegt, blendet der
// Shader ueber `bounds` aus.
#[allow(clippy::too_many_arguments)]
// Vanillas Schatten: ein Viertel der Textfarbe -- gerechnet im ANZEIGE-Raum (sRGB), wie
// Vanilla es tut. Die UI-Farben hier sind linear; ein Viertel davon kaeme auf der
// sRGB-Oberflaeche als helles Grau heraus (fuer weissen Text ~54 % statt 25 %), der Schatten
// sah fast weiss aus.
fn vanilla_shadow_color(c: [f32; 4]) -> [f32; 4] {
    let viertel = |v: f32| world::sky::srgb_to_linear(world::sky::linear_to_srgb(v) * 0.25);
    [viertel(c[0]), viertel(c[1]), viertel(c[2]), c[3]]
}

// Schwarz (lineare Farbe, bis etwa sRGB 25/255): ein schwarzer Rand um schwarze Schrift macht
// sie nur dicker und unscharf, deshalb bekommt sie keinen (s. shape_text_in, world_text_border).
fn is_black(c: [f32; 4]) -> bool {
    c[0].max(c[1]).max(c[2]) < 0.01
}

// `staerke`: bei der Kontur ihre Dicke in Bildschirmpixeln, sonst die Deckkraft (0..1) des
// Rands (s. Settings::shadow_strength).
fn text_border_quad(
    stil: TextShadow,
    staerke: f32,
    [x0, y0, x1, y1]: [f32; 4],
    uv_min: [f32; 2],
    uv_max: [f32; 2],
    scale: f32,
    snap: bool,
    farbe: [f32; 4],
    screen_px: (f32, f32),
) -> [TextVertex; 6] {
    // Bei den weichen Raendern darf die Staerke ueber 1 gehen (s. Settings::shadow_strength),
    // font.wgsl begrenzt die Deckung.
    let grenze = if matches!(stil, TextShadow::Below | TextShadow::Around) { 100.0 / SOFT_SHADOW_FULL_PERCENT } else { 1.0 };
    let farbe = if stil == TextShadow::Outline { farbe } else { [farbe[0], farbe[1], farbe[2], farbe[3] * staerke.clamp(0.0, grenze)] };
    let je_px = [(uv_max[0] - uv_min[0]) / (x1 - x0), (uv_max[1] - uv_min[1]) / (y1 - y0)];
    let bounds = [uv_min[0], uv_min[1], uv_max[0], uv_max[1]];
    match stil {
        TextShadow::Below | TextShadow::Around => {
            // Unschaerfe mit der Schrift wachsend; "Unten" zusaetzlich um dasselbe Mass nach
            // unten versetzt, "Aussen" ohne Versatz.
            let b = (scale * 0.9).max(1.5);
            let (art, v) = if stil == TextShadow::Below { (TEXT_MODE_BELOW, b) } else { (TEXT_MODE_AROUND, 0.0) };
            text_quad_fx(
                x0 - b,
                y0 - b,
                x1 + b,
                y1 + v + b,
                [uv_min[0] - je_px[0] * b, uv_min[1] - je_px[1] * b],
                [uv_max[0] + je_px[0] * b, uv_max[1] + je_px[1] * (v + b)],
                farbe,
                bounds,
                [art, je_px[0], je_px[1], b],
                screen_px,
            )
        }
        TextShadow::Vanilla => {
            // Ein Schriftpixel; bei pixelgenau gesetzten Glyphen ganzzahlig.
            let v = if snap { scale.round().max(1.0) } else { scale };
            text_quad_fx(
                x0,
                y0,
                x1 + v,
                y1 + v,
                uv_min,
                [uv_max[0] + je_px[0] * v, uv_max[1] + je_px[1] * v],
                farbe,
                bounds,
                [TEXT_MODE_SHADOW, je_px[0], je_px[1], v],
                screen_px,
            )
        }
        _ => {
            // Die Kontur reicht `dicke` Pixel weit, das Viereck ringsum auf ganze Pixel.
            let dicke = staerke.clamp(0.5, 4.0);
            let d = dicke.ceil();
            text_quad_fx(
                x0 - d,
                y0 - d,
                x1 + d,
                y1 + d,
                [uv_min[0] - je_px[0] * d, uv_min[1] - je_px[1] * d],
                [uv_max[0] + je_px[0] * d, uv_max[1] + je_px[1] * d],
                farbe,
                bounds,
                [TEXT_MODE_OUTLINE, je_px[0], je_px[1], dicke],
                screen_px,
            )
        }
    }
}

// Eine Textauswahl mit der Maus: Anfangspunkt, aktueller Punkt, und in welchem Bildschirm
// sie entstand. Gespeichert werden PUNKTE, keine Zeichenindizes: der Text wird jedes Bild neu
// gesetzt, und die Auswahl ergibt sich jedes Mal neu aus dem, was an diesen Stellen steht (s.
// select_in_runs). Wechselt der Bildschirm, gilt sie nicht mehr.
#[derive(Clone)]
struct TextSelection {
    anchor: (f32, f32),
    focus: (f32, f32),
    dragging: bool,
    // Erst nach ein paar Pixeln Ziehen wird ein Klick zur Auswahl -- ein gewoehnlicher Klick
    // soll nichts markieren.
    moved: bool,
    // 1 = zeichenweise, 2 = wortweise (Doppelklick), 3 = zeilenweise (Dreifachklick). Ab 2
    // gilt die Auswahl sofort, ohne Ziehen, und Ziehen erweitert in ganzen Woertern/Zeilen.
    clicks: u8,
    context: SelectionContext,
    // Im Chatverlauf begonnen: (Zeilenstand, Zeilenhoehe) beim Druecken (s. App::chat_view).
    // Die Punkte sind dann relativ zu DIESEM Stand gespeichert -- rueckt der Chat nach oben
    // (neue Nachricht, Blaettern), wandert die Auswahl mit ihrem Text mit. Vorher
    // blieb sie an derselben Bildschirmstelle und markierte dann fremden Text.
    chat_anchor: Option<(usize, f32)>,
}

// Zwei Klicks gelten als Doppel-/Dreifachklick, wenn sie so kurz nacheinander und so nah
// beieinander kommen (uebliche Desktop-Werte).
const MULTI_CLICK_MS: u128 = 450;
const MULTI_CLICK_PX: f32 = 5.0;

// Wo eine Auswahl gilt: Modus, Menue-Bildschirm und welche Overlays offen sind.
type SelectionContext = (AppMode, MenuScreen, bool, bool);

// Mindestweg (Pixel), ab dem aus einem Klick eine Auswahl wird.
const SELECTION_DRAG_MIN: f32 = 4.0;
const COLOR_SELECTION: [f32; 4] = [0.25, 0.5, 1.0, 0.45];

// Toleranz, ab der zwei Zeilen als verschiedene Zeilen gelten (Pixel).
const SELECTION_LINE_EPS: f32 = 2.0;

// Die "Zeile", auf der ein Punkt liegt: Oberkante des Textstreifens, der ihn enthaelt, sonst
// sein eigenes y.
fn selection_line_of(runs: &[TextRun], p: (f32, f32)) -> f32 {
    runs.iter().find(|r| p.1 >= r.top && p.1 < r.bottom).map(|r| r.top).unwrap_or(p.1)
}

// Liegt ein Zeichen (Zeile `top`, Mitte `mid`) in Lesereihenfolge an oder hinter dem Punkt?
fn selection_after(top: f32, mid: f32, line: f32, x: f32) -> bool {
    top > line + SELECTION_LINE_EPS || ((top - line).abs() <= SELECTION_LINE_EPS && mid >= x)
}

// Alle Zeichen der Bildschirmzeile ab Oberkante `top`, nach x sortiert -- ueber alle
// Textstuecke hinweg (ein Farbwechsel im Chat ist ein eigenes Stueck, gehoert aber zur Zeile).
fn line_glyphs(runs: &[TextRun], top: f32) -> Vec<(char, f32, f32)> {
    let mut g: Vec<(char, f32, f32)> =
        runs.iter().filter(|r| (r.top - top).abs() <= SELECTION_LINE_EPS).flat_map(|r| r.glyphs.iter().copied()).collect();
    g.sort_by(|a, b| a.1.total_cmp(&b.1));
    g
}

// Waagerechter Bereich [x0, x1) des Wortes unter dem Punkt (Doppelklick). Ein Wort endet an
// Leerraum und an Luecken zwischen getrennt stehenden Texten (Beschriftung links, Wert
// rechts). Auf Leerraum selbst: nur dieses eine Zeichen. None = kein Text unter dem Punkt.
fn word_bounds(runs: &[TextRun], p: (f32, f32)) -> Option<(f32, f32)> {
    let run = runs.iter().find(|r| p.1 >= r.top && p.1 < r.bottom)?;
    let g = line_glyphs(runs, run.top);
    let i = g.iter().position(|&(_, x0, x1)| p.0 >= x0 && p.0 < x1)?;
    if g[i].0.is_whitespace() {
        return Some((g[i].1, g[i].2));
    }
    let zum_wort = |a: &(char, f32, f32), b: &(char, f32, f32)| !a.0.is_whitespace() && !b.0.is_whitespace() && b.1 - a.2 <= 2.0;
    let (mut von, mut bis) = (i, i);
    while von > 0 && zum_wort(&g[von - 1], &g[von]) {
        von -= 1;
    }
    while bis + 1 < g.len() && zum_wort(&g[bis], &g[bis + 1]) {
        bis += 1;
    }
    Some((g[von].1, g[bis].2))
}

// Waagerechter Bereich des zusammenhaengenden Textblocks unter dem Punkt (Dreifachklick):
// die Zeile, aber nur so weit, wie der Text ohne grosse Luecke weiterlaeuft. Eine Luecke von
// mehr als einer Zeilenhoehe trennt zwei Texte, die zufaellig auf derselben Hoehe stehen --
// sonst nahm etwa ein Dreifachklick auf die Chunk-Statistik im Pausemenue den
// "Disconnect"-Knopf daneben mit.
fn line_block_bounds(runs: &[TextRun], p: (f32, f32)) -> Option<(f32, f32)> {
    let run = runs.iter().find(|r| p.1 >= r.top && p.1 < r.bottom)?;
    let luecke = run.bottom - run.top;
    let g = line_glyphs(runs, run.top);
    if g.is_empty() {
        return None;
    }
    // Der Block, in dem der Punkt liegt -- oder der naechste, wenn er zwischen zwei steht.
    let mut bloecke: Vec<(f32, f32)> = Vec::new();
    for &(_, x0, x1) in &g {
        match bloecke.last_mut() {
            Some(b) if x0 - b.1 <= luecke => b.1 = b.1.max(x1),
            _ => bloecke.push((x0, x1)),
        }
    }
    let abstand = |b: &(f32, f32)| (b.0 - p.0).max(p.0 - b.1).max(0.0);
    bloecke.into_iter().min_by(|x, y| abstand(x).total_cmp(&abstand(y)))
}

// Auswahl in ganzen Woertern (clicks = 2) oder ganzen Zeilen (clicks = 3) zwischen zwei
// Punkten: beide Enden werden auf ihre Wort- bzw. Zeilengrenzen erweitert.
fn select_in_runs_by_unit(runs: &[TextRun], a: (f32, f32), b: (f32, f32), clicks: u8) -> Vec<(usize, std::ops::Range<usize>)> {
    // Nur Text aus dem Bereich des Ankers zaehlt (s. selection_boundary).
    let bereich = anchor_group(runs, a);
    let eigene: Vec<TextRun> = runs.iter().filter(|r| Some(r.group) == bereich).cloned().collect();
    let grenzen = |p: (f32, f32)| {
        if clicks >= 3 {
            line_block_bounds(&eigene, p).unwrap_or((p.0, p.0))
        } else {
            word_bounds(&eigene, p).unwrap_or((p.0, p.0))
        }
    };
    let (la, lb) = (selection_line_of(runs, a), selection_line_of(runs, b));
    let b_zuerst = lb + SELECTION_LINE_EPS < la || ((lb - la).abs() <= SELECTION_LINE_EPS && b.0 < a.0);
    let (s, e) = if b_zuerst { (b, a) } else { (a, b) };
    let (sg, eg) = (grenzen(s), grenzen(e));
    // Mitten liegen innerhalb des Wortes, also: Anfang = Wortanfang, Ende = Wortende. Der
    // Bereich kommt vom ANKER a, nicht vom (evtl. vertauschten) Anfang.
    let ergebnis = select_in_runs_of_group(runs, (sg.0, s.1), (eg.1, e.1), bereich);
    // Ein Punkt ohne Text darunter (Wortgrenzen (x, x)) liefert fuer sich allein nichts.
    if ergebnis.is_empty() && clicks < 3 {
        return Vec::new();
    }
    ergebnis
}

// Welche Zeichen zwischen zwei Punkten liegen -- wie im Browser in LESEREIHENFOLGE (Zeile
// fuer Zeile, links nach rechts), nicht als Rechteck. Ergebnis: je betroffener Zeile deren
// Index und der Zeichenbereich.
fn select_in_runs(runs: &[TextRun], a: (f32, f32), b: (f32, f32)) -> Vec<(usize, std::ops::Range<usize>)> {
    let bereich = anchor_group(runs, a);
    select_in_runs_of_group(runs, a, b, bereich)
}

// Der Auswahlbereich unter dem Anfangspunkt: die Zeile, die ihn enthaelt, sonst die naechste.
fn anchor_group(runs: &[TextRun], a: (f32, f32)) -> Option<u32> {
    let abstand = |r: &TextRun| {
        let (x0, x1) = match (r.glyphs.first(), r.glyphs.last()) {
            (Some(f), Some(l)) => (f.1, l.2),
            _ => return f32::INFINITY,
        };
        let dx = (x0 - a.0).max(a.0 - x1).max(0.0);
        let dy = (r.top - a.1).max(a.1 - r.bottom).max(0.0);
        dx * dx + dy * dy
    };
    runs.iter().min_by(|p, q| abstand(p).total_cmp(&abstand(q))).filter(|r| abstand(r).is_finite()).map(|r| r.group)
}

fn select_in_runs_of_group(runs: &[TextRun], a: (f32, f32), b: (f32, f32), bereich: Option<u32>) -> Vec<(usize, std::ops::Range<usize>)> {
    let Some(bereich) = bereich else { return Vec::new() };
    let im_bereich: Vec<TextRun> = runs.iter().map(|r| if r.group == bereich { r.clone() } else { TextRun { glyphs: Vec::new(), ..r.clone() } }).collect();
    let runs = &im_bereich[..];
    let (la, lb) = (selection_line_of(runs, a), selection_line_of(runs, b));
    // Anfang = der Punkt, der in Lesereihenfolge zuerst kommt.
    let b_zuerst = lb + SELECTION_LINE_EPS < la || ((lb - la).abs() <= SELECTION_LINE_EPS && b.0 < a.0);
    let ((ls, s), (le, e)) = if b_zuerst { ((lb, b), (la, a)) } else { ((la, a), (lb, b)) };
    let mut out = Vec::new();
    for (i, run) in runs.iter().enumerate() {
        let mut von = None;
        let mut bis = 0;
        for (j, &(_, x0, x1)) in run.glyphs.iter().enumerate() {
            let mid = (x0 + x1) / 2.0;
            if selection_after(run.top, mid, ls, s.0) && !selection_after(run.top, mid, le, e.0) {
                von.get_or_insert(j);
                bis = j + 1;
            }
        }
        if let Some(v) = von {
            out.push((i, v..bis));
        }
    }
    out
}

// Der ausgewaehlte Text: Zeilen durch Zeilenumbrueche getrennt, Stuecke derselben Zeile nach
// x geordnet und -- wo zwischen ihnen Luft ist -- durch ein Leerzeichen.
fn selection_text(runs: &[TextRun], sel: &[(usize, std::ops::Range<usize>)]) -> String {
    let mut stuecke: Vec<(f32, f32, f32, String)> = sel
        .iter()
        .map(|(i, r)| {
            let run = &runs[*i];
            let g = &run.glyphs[r.clone()];
            (run.top, g[0].1, g[g.len() - 1].2, g.iter().map(|(c, _, _)| *c).collect())
        })
        .collect();
    stuecke.sort_by(|a, b| a.0.total_cmp(&b.0).then(a.1.total_cmp(&b.1)));
    let mut text = String::new();
    let mut vorher: Option<(f32, f32)> = None;
    for (top, x0, x1, s) in stuecke {
        match vorher {
            Some((t, _)) if (top - t).abs() > SELECTION_LINE_EPS => {
                let ende = text.trim_end().len();
                text.truncate(ende);
                text.push('\n');
            }
            Some((_, ende)) if x0 - ende > 2.0 && !text.ends_with(' ') && !s.starts_with(' ') => text.push(' '),
            _ => {}
        }
        text.push_str(&s);
        vorher = Some((top, x1));
    }
    text.trim_end().to_string()
}

// Eine gesetzte Chatzeile: Einzug (Bildschirmpixel) und die farbigen Abschnitte.
#[derive(Clone, Debug, PartialEq)]
struct ChatLine {
    indent: f32,
    spans: Vec<protocol::nbt::TextSpan>,
}

// Wo die Folgezeilen einer umbrochenen Nachricht anfangen: immer fest zwei Leerzeichen vom
// linken Chatrand. (Eine Fassung, die buendig unter dem Text nach "<Name> " weiterlief, war
// nicht gewollt -- so sind Folgezeilen gleichmaessig und sofort als solche zu erkennen.)
fn chat_hanging_indent(measure: &impl Fn(&str) -> f32) -> f32 {
    measure("  ")
}

// Eine Chatnachricht auf `max_width` Pixel setzen.
//
//  - Zeilenumbrueche ("\n") im Text werden umgesetzt. Frueher liefen die Zeilen einfach
//    ineinander: der Umbruch hat keine Glyphe und verschwand.
//  - Umbrochene Folgezeilen werden fest eingerueckt (s. chat_hanging_indent) und bekommen
//    entsprechend weniger Breite.
//  - Leerzeichen am Anfang einer Server-Zeile bleiben stehen (Server richten damit aus), das
//    Leerzeichen, an dem umbrochen wurde, faellt weg.
//  - Ein Wort, das allein zu breit ist, wird zeichenweise zerlegt.
fn wrap_chat_message(msg: &[protocol::nbt::TextSpan], max_width: f32, measure: impl Fn(&str) -> f32) -> Vec<ChatLine> {
    let einzug = chat_hanging_indent(&measure);
    wrap_spans(msg, max_width, measure, einzug)
}

// Farbige Abschnitte auf `max_width` setzen wie wrap_chat_message, Folgezeilen um `einzug`
// eingerueckt (0 = buendig, wie Vanillas Font.split fuer Buchseiten).
fn wrap_spans(msg: &[protocol::nbt::TextSpan], max_width: f32, measure: impl Fn(&str) -> f32, einzug: f32) -> Vec<ChatLine> {
    let absaetze = split_label_lines(msg);
    let mut out = Vec::new();
    for absatz in absaetze {
        let mut aktuell: Vec<protocol::nbt::TextSpan> = Vec::new();
        let mut breite = 0.0f32;
        let mut zeilen_einzug = 0.0f32;
        let mut umbrochen = false;
        let anfuegen = |aktuell: &mut Vec<protocol::nbt::TextSpan>, text: &str, span: &protocol::nbt::TextSpan| match aktuell.last_mut() {
            Some(last) if last.color == span.color && last.link == span.link && last.action == span.action => last.text.push_str(text),
            _ => aktuell.push(protocol::nbt::TextSpan { text: text.to_string(), color: span.color, link: span.link.clone(), action: span.action.clone(), style: span.style, shadow: span.shadow }),
        };
        for span in &absatz {
            for (i, wort) in span.text.split(' ').enumerate() {
                // Das Leerzeichen VOR dem Wort gehoert dazu -- ausser direkt nach einem
                // Umbruch, dort faellt es weg.
                let mit_luecke = if i > 0 && !(umbrochen && aktuell.is_empty()) { format!(" {wort}") } else { wort.to_string() };
                if mit_luecke.is_empty() {
                    continue;
                }
                let grenze = max_width - zeilen_einzug;
                let w = measure(&mit_luecke);
                if breite > 0.0 && breite + w > grenze {
                    out.push(ChatLine { indent: zeilen_einzug, spans: std::mem::take(&mut aktuell) });
                    breite = 0.0;
                    zeilen_einzug = einzug;
                    umbrochen = true;
                }
                let stueck = if aktuell.is_empty() && umbrochen { wort } else { mit_luecke.as_str() };
                if stueck.is_empty() {
                    continue;
                }
                let grenze = max_width - zeilen_einzug;
                if measure(stueck) > grenze {
                    for teil in hard_break(&measure, stueck, grenze.min(max_width - einzug).max(1.0)) {
                        if breite > 0.0 {
                            out.push(ChatLine { indent: zeilen_einzug, spans: std::mem::take(&mut aktuell) });
                            breite = 0.0;
                            zeilen_einzug = einzug;
                            umbrochen = true;
                        }
                        breite += measure(&teil);
                        anfuegen(&mut aktuell, &teil, span);
                    }
                    continue;
                }
                breite += measure(stueck);
                anfuegen(&mut aktuell, stueck, span);
            }
        }
        out.push(ChatLine { indent: zeilen_einzug, spans: aktuell });
    }
    out
}

// Ein Text aus Vanillas Sprachdatei (der Sprache des Spiels), sonst der englische.
fn vanilla_text(key: &str, standard: &str) -> String {
    protocol::nbt::translate(key).unwrap_or_else(|| standard.to_string())
}

// Nackte Adressen im Text klickbar machen ("https://..." bis zum naechsten Leerzeichen).
// Vanilla macht das fuer Spielernachrichten ebenso; Server, die selbst ein ClickEvent setzen,
// haben ihren Link schon (s. nbt::TextSpan::link) und bleiben unangetastet.
fn linkify_chat(spans: Vec<protocol::nbt::TextSpan>) -> Vec<protocol::nbt::TextSpan> {
    let mut out = Vec::with_capacity(spans.len());
    for span in spans {
        let eigener_klick = span.action.as_ref().is_some_and(|a| a.click.is_some());
        if span.link.is_some() || eigener_klick || !(span.text.contains("http://") || span.text.contains("https://")) {
            out.push(span);
            continue;
        }
        let mut rest = span.text.as_str();
        while let Some(start) = ["https://", "http://"].iter().filter_map(|p| rest.find(p)).min() {
            let ende = rest[start..].find(char::is_whitespace).map(|e| start + e).unwrap_or(rest.len());
            // Satzzeichen direkt hinter der Adresse gehoeren nicht dazu ("siehe https://a.b.").
            let url = rest[start..ende].trim_end_matches(['.', ',', ')', '!', '?', ';', ':', '"', '\'']);
            let ende = start + url.len();
            if start > 0 {
                out.push(protocol::nbt::TextSpan { text: rest[..start].to_string(), color: span.color, link: None, action: span.action.clone(), style: span.style, shadow: span.shadow });
            }
            out.push(protocol::nbt::TextSpan { text: url.to_string(), color: span.color, link: Some(url.to_string()), action: span.action.clone(), style: span.style, shadow: span.shadow });
            rest = &rest[ende..];
        }
        if !rest.is_empty() {
            out.push(protocol::nbt::TextSpan { text: rest.to_string(), color: span.color, link: None, action: span.action.clone(), style: span.style, shadow: span.shadow });
        }
    }
    out
}

// Ein Farbkanal 0..255 aus Vanilla (sRGB-Wert) -> linearer Wert der UI. Die Oberflaeche ist
// ein sRGB-Ziel und kodiert beim Schreiben selbst; ungewandelt kamen alle Server-Farben zu
// hell an (etwa Chat-Textfarben). Alpha bleibt linear.
fn srgb_channel(v: u32) -> f32 {
    world::sky::srgb_to_linear((v & 0xFF) as f32 / 255.0)
}

// 0xAARRGGBB (Vanillas Hintergrundfarbe) -> die Vec4-Form der UI.
fn argb_to_rgba(argb: i32) -> [f32; 4] {
    let v = argb as u32;
    [srgb_channel(v >> 16), srgb_channel(v >> 8), srgb_channel(v), ((v >> 24) & 0xFF) as f32 / 255.0]
}

// Vanilla mischt halbdurchsichtige Flaechen im sRGB-Raum (OpenGL ohne sRGB-Framebuffer),
// unsere Oberflaeche ist ein sRGB-Ziel und mischt LINEAR. Dieselbe Deckkraft wirkt dadurch
// ganz anders: Vanillas weisser Zeilenschleier der Tab-Liste (0x20FFFFFF) hebt dunklen Grund
// um 12,5 % der ANZEIGE-Helligkeit, linear gemischt aber um 12,5 % der Lichtmenge -- das
// sind rund 39 % Anzeige-Helligkeit, und die Zeilen wirken milchig weiss. Umgerechnet wird so, dass das Ergebnis dort exakt stimmt, wo
// der Unterschied am groessten ist: ein weisser Schleier ueber Schwarz, ein schwarzer ueber
// Weiss. Dazwischen weicht es nur noch wenig ab.
fn white_veil(alpha: f32) -> [f32; 4] {
    [1.0, 1.0, 1.0, world::sky::srgb_to_linear(alpha)]
}

// Gegenstueck zu white_veil fuer schwarze Hintergruende.
// Abdunklung hinter Fenstern in der Bildschirmmitte (Quick Connect, Acc-Manager, Server-
// Eintrag, Buch, Schild): ueberall dieselbe, halbe Helligkeit.
fn dialog_dim() -> [f32; 4] {
    black_veil(0.5)
}

fn black_veil(alpha: f32) -> [f32; 4] {
    [0.0, 0.0, 0.0, 1.0 - world::sky::srgb_to_linear(1.0 - alpha)]
}

// 0xRRGGBB (Textfarbe eines Components) -> die Vec4-Form der UI, voll deckend.
fn rgb_to_rgba(rgb: u32) -> [f32; 4] {
    [srgb_channel(rgb >> 16), srgb_channel(rgb >> 8), srgb_channel(rgb), 1.0]
}

// --- Masse der Statusleisten (GUI-Einheiten, s. build_status_bars) --------------------------
// Ein Symbol ist 9x9 und steht im 8er-Raster -- die Symbole ueberlappen sich also um einen
// Pixel, genau wie in Vanilla.
const STATUS_ICON: f32 = 9.0;
const STATUS_ICON_PITCH: f32 = 8.0;
// Abstand zweier Leisten-Zeilen (Ruestung ueber Leben, Luft ueber Nahrung).
const STATUS_ROW_PITCH: f32 = 10.0;
// Breite der Hotbar und damit auch der Erfahrungsleiste; die rechte Kante ist der Nullpunkt
// fuer Nahrung und Luft.
const STATUS_BAR_WIDTH: f32 = 182.0;
// Wie weit ueber der Hotbar-Oberkante die jeweilige Zeile sitzt (Vanilla-Werte, umgerechnet:
// Herzen height-39, Erfahrungsleiste height-29, Stufenzahl height-35, Hotbar-Oberkante
// height-22).
const STATUS_BARS_ABOVE_HOTBAR: f32 = 17.0;
const XP_BAR_ABOVE_HOTBAR: f32 = 7.0;
const XP_LEVEL_ABOVE_HOTBAR: f32 = 13.0;
const XP_BAR_HEIGHT: f32 = 5.0;
// Vanillas Gruen der Stufenzahl (-8323296 = 0x80FF20).
const COLOR_XP_LEVEL: [f32; 4] = [0.5, 1.0, 0.125, 1.0];
// Entity.getMaxAir(): 300 Ticks = 15 Sekunden unter Wasser.
const MAX_AIR_TICKS: i32 = 300;

// Halbtransparenter Hintergrund der Scoreboard-Seitenleiste (wie Vanilla ~40% Schwarz).
const COLOR_SCOREBOARD_BG: [f32; 4] = [0.0, 0.0, 0.0, 0.4];
// --- Tab-Liste (PlayerListHud) ---
// Hintergrund von Kopf, Liste und Fuss: Integer.MIN_VALUE = Schwarz mit halber Deckkraft.
// Deckkraft so, wie Vanilla sie im sRGB-Raum mischt (s. black_veil).
const PLAYER_LIST_BG_ALPHA: f32 = 0.5;
// Jede Zeile: 0x20FFFFFF (Vanillas Vorgabe fuer getTextBackgroundColor), s. white_veil.
const PLAYER_LIST_ROW_ALPHA: f32 = 32.0 / 255.0;
// Zuschauernamen: 0x90FFFFFF.
const PLAYER_LIST_SPECTATOR_ALPHA: f32 = 144.0 / 255.0;
