// in dieser Zeit herein bzw. hinaus.
const NOTIFICATION_PANEL_SLIDE: f32 = 0.22;
fn notification_panel_w(screen_w: f32) -> f32 {
    (screen_w / 4.0).max(320.0).min(screen_w).round()
}

const SETTINGS_HUB_BTN_W: f32 = 300.0;
const SETTINGS_HUB_BTN_H: f32 = 52.0;
const SETTINGS_HUB_FIRST_Y: f32 = 140.0;
const SETTINGS_HUB_ROW_H: f32 = 68.0;
const SETTINGS_HUB_COLS: usize = 4;
const SETTINGS_HUB_COL_GAP: f32 = 16.0;
// Kachel `i` von `count`: vier Spalten, als Block mittig, SPALTENWEISE gefuellt -- die
// (alphabetisch sortierte, s. buttons()) Reihenfolge laeuft erst in der ersten Spalte nach
// unten, dann in der naechsten.
fn settings_hub_button(i: usize, count: usize, screen_w: f32) -> Rect {
    let rows = count.div_ceil(SETTINGS_HUB_COLS).max(1);
    let (col, row) = (i / rows, i % rows);
    let block_w = SETTINGS_HUB_COLS as f32 * SETTINGS_HUB_BTN_W + (SETTINGS_HUB_COLS - 1) as f32 * SETTINGS_HUB_COL_GAP;
    let x0 = ((screen_w - block_w) / 2.0).round().max(UI_MARGIN);
    Rect {
        x: x0 + col as f32 * (SETTINGS_HUB_BTN_W + SETTINGS_HUB_COL_GAP),
        y: SETTINGS_HUB_FIRST_Y + row as f32 * SETTINGS_HUB_ROW_H,
        w: SETTINGS_HUB_BTN_W,
        h: SETTINGS_HUB_BTN_H,
    }
}

// Trefferflaeche fuer den Hover-Tooltip einer Einstellungszeile -- deckt Beschriftung UND
// Bedienelement ab (breiter als SETTINGS_CTRL_X + STEPPER_VALUE_W, damit der ganze Stepper
// samt Pfeilen mit reinfaellt), volle Zeilenhoehe statt nur SETTINGS_CTRL_H (grosszuegigere
// Trefferflaeche, kein Zittern beim Rand-Ueberfahren).
fn settings_row_hover_rect(row: usize) -> Rect {
    Rect { x: SETTINGS_LABEL_X, y: settings_row_y(row), w: 700.0, h: SETTINGS_ROW_H }
}

// Pixel je Millimeter des Bildschirms (aus der EDID, s. monitor_size), als f32-Bits; 0 = unbekannt.
static PX_PER_MM: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);

fn px_per_mm() -> f32 {
    let v = f32::from_bits(PX_PER_MM.load(std::sync::atomic::Ordering::Relaxed));
    // Ohne EDID: 96 dpi.
    if v > 0.0 { v } else { 96.0 / 25.4 }
}

// Rand rechts auf den Einstellungsseiten, in dem die Erklaerung zur Zeile unter dem Zeiger
// steht: 10 cm, auf kleinen Bildschirmen hoechstens ein Viertel der Breite.
fn tooltip_strip_w(screen_w: f32) -> f32 {
    (100.0 * px_per_mm()).min(screen_w * 0.25).round()
}

// Fester Bildschirmbereich rechts fuer den Hover-Tooltip (s. hovered_tooltip) -- bewusst
// NICHT am Mauszeiger, damit die Erklaerung nicht bei jeder Mausbewegung mitspringt und
// nicht ausgerechnet die Zeile verdeckt, die sie erklaert. Hoehe ergibt sich aus dem
// Text (s. Aufrufer), nur x/y/Breite stehen hier fest.
const TOOLTIP_PANEL_W: f32 = 460.0;
const TOOLTIP_PANEL_MARGIN: f32 = 40.0;
// (x, y, Breite) -- die Hoehe haengt vom umgebrochenen Text ab und wird beim Aufrufer
// berechnet, deshalb kein Rect mit einer Blindattrappen-Hoehe hier.
fn tooltip_panel_origin(screen_w: f32) -> (f32, f32, f32) {
    (screen_w - TOOLTIP_PANEL_W - TOOLTIP_PANEL_MARGIN, SETTINGS_FIRST_Y, TOOLTIP_PANEL_W)
}

// Zerlegt einen Tooltip-Text in Zeilen, die je hoechstens `max_width` Pixel breit sind --
// an Wortgrenzen umgebrochen (misst echte Pixelbreite ueber den Font-Atlas statt grob nach
// Zeichenzahl zu schaetzen, s. gpu.measure_text). Fuer Tooltips: kurze, feste Erklaerungen,
// kein Layout-kritischer Pfad, daher ist die pro-Wort-Neumessung hier unproblematisch.
// Mausrad: so viele Pixel eines Touchpads zaehlen als eine Raste.
const WHEEL_PIXELS_PER_NOTCH: f32 = 40.0;
// Einstellungslisten (Tastenbelegungen, Modul-Menue) scrollen eine Zeile je Raste.
const SETTINGS_SCROLL_ROWS_PER_NOTCH: f32 = 1.0;
// Lautstaerke per Mausrad (s. App::wheel_notch): Schritt je Raste in Prozent -- derselbe wie
// die Pfeile im Audio-Tab.
const VOLUME_WHEEL_STEP: u32 = 5;
// Gehaltene Lautstaerke-Taste: erste Wiederholung nach der Pause, danach im Takt (20 %/s).
const VOLUME_KEY_REPEAT_DELAY: Duration = Duration::from_millis(400);
const VOLUME_KEY_REPEAT: Duration = Duration::from_millis(50);
// Anzeige links: Einfahren, Stehen nach der letzten Raste, Ausblenden (Sekunden).
const VOLUME_DISPLAY_ENTER: f32 = 0.25;
const VOLUME_DISPLAY_HOLD: f32 = 1.2;
const VOLUME_DISPLAY_FADE: f32 = 0.3;
const VOLUME_DISPLAY_W: f32 = 200.0;
const VOLUME_DISPLAY_MARGIN: f32 = 16.0;
const VOLUME_BAR_H: f32 = 6.0;

// Aufbau einer Benachrichtigungskarte (s. App::build_notifications): links ein farbiger
// Streifen, daneben Titel und umbrochener Text, unten die Leiste mit der Reststandzeit.
const NOTIFICATION_ACCENT_W: f32 = 4.0;
const NOTIFICATION_PADDING: f32 = 12.0;
const NOTIFICATION_BODY_GAP: f32 = 6.0;
const NOTIFICATION_TIMER_H: f32 = 2.0;
const COLOR_NOTIFICATION_BG: [f32; 4] = [0.08, 0.08, 0.10, 0.94];
const COLOR_NOTIFICATION_BG_HOVER: [f32; 4] = [0.13, 0.13, 0.16, 0.96];
const COLOR_NOTIFICATION_BODY: [f32; 4] = [0.72, 0.72, 0.76, 1.0];

struct NotificationLayout {
    title: Vec<String>,
    body: Vec<String>,
    height: f32,
}

fn notification_line_h(gpu: &GpuState) -> f32 {
    gpu.text_height(UI_SCALE_SMALL) + 4.0
}

// Eine Quelle fuer Hoehe (Stapeln, Trefferpruefung) und Zeichnen -- sonst laege der
// anklickbare Bereich neben der gezeichneten Karte, sobald sich eins von beiden aendert.
fn notification_layout(gpu: &GpuState, note: &notifications::Notification) -> NotificationLayout {
    let breite = notifications::CARD_WIDTH - NOTIFICATION_ACCENT_W - 2.0 * NOTIFICATION_PADDING;
    // Auch der Titel bricht um: er traegt oft einen Namen (Geraet, Spieler), dessen Laenge
    // niemand vorher kennt.
    let title = wrap_text(gpu, &note.title, UI_SCALE_SMALL, breite);
    let body = if note.body.is_empty() { Vec::new() } else { wrap_text(gpu, &note.body, UI_SCALE_SMALL, breite) };
    let mut height = 2.0 * NOTIFICATION_PADDING + title.len().max(1) as f32 * notification_line_h(gpu) - 4.0;
    if !body.is_empty() {
        height += NOTIFICATION_BODY_GAP + body.len() as f32 * notification_line_h(gpu) - 4.0;
    }
    NotificationLayout { title, body, height }
}

// Eine Zeile aus Farbabschnitten zeichnen, ausgerichtet wie EIN Text (s.
// GpuState::char_positions). Zerlegt wird zusaetzlich an jeder Grenze zwischen Ziffer und
// Nicht-Ziffer: so beginnt jede Zahl an ihrem reservierten Platz, und alles dahinter steht
// fest. Die Ziffern-Stuecke sind reine Zahlen und werden in shape_text nicht noch einmal
// verschoben (s. stable_numbers::pattern).
fn push_stable_spans(
    gpu: &GpuState,
    spans: &[protocol::nbt::TextSpan],
    x: f32,
    y: f32,
    default: [f32; 4],
    scale: f32,
    texts: &mut Vec<UiText>,
    rects: &mut Vec<UiRect>,
) {
    let voll: String = spans.iter().map(|s| s.text.as_str()).collect();
    let (pos, gesamt) = gpu.char_positions(&voll, scale);
    // Fette Zeichen haben einen Font-Pixel mehr Vorschub (s. push_bold_marker): wie viele
    // davon vor Zeichen i stehen.
    let mut fette_davor = vec![0usize];
    for span in spans {
        let fett = span.style & protocol::nbt::STYLE_BOLD != 0;
        for _ in span.text.chars() {
            fette_davor.push(fette_davor.last().unwrap() + fett as usize);
        }
    }
    let bei = |i: usize| pos.get(i).copied().unwrap_or(gesamt) + fette_davor.get(i).or(fette_davor.last()).copied().unwrap_or(0) as f32 * scale;
    let mut i = 0;
    for span in spans {
        let farbe = span.color.map(rgb_to_rgba).unwrap_or(default);
        let text = styled_text(span);
        let erstes = i;
        let mut stueck = String::new();
        let mut anfang = i;
        let mut ziffer: Option<bool> = None;
        let mut stuecke = Vec::new();
        for ch in text.chars() {
            let d = ch.is_ascii_digit();
            if ziffer.is_some_and(|z| z != d) {
                stuecke.push((std::mem::take(&mut stueck), x + bei(anfang)));
                anfang = i;
            }
            ziffer = Some(d);
            stueck.push(ch);
            i += 1;
        }
        if !stueck.is_empty() {
            stuecke.push((stueck, x + bei(anfang)));
        }
        for (t, sx) in stuecke {
            push_styled_piece(span.style, span.shadow, t, sx, y, farbe, scale, texts);
        }
        span_lines(gpu, span.style, x + bei(erstes), x + bei(i), y, farbe, scale, &mut |r| rects.push(UiRect { rect: r, color: farbe, ..UiRect::FLAT }));
    }
}

// Ein Stueck Text, fett ueber push_bold_marker.
// `shadow`: die Schattenfarbe des Servers (s. push_span_shadow), fuer beide Durchgaenge.
fn push_styled_piece(style: u8, shadow: Option<u32>, text: String, x: f32, y: f32, color: [f32; 4], scale: f32, texts: &mut Vec<UiText>) {
    if style & protocol::nbt::STYLE_BOLD != 0 {
        push_bold_marker(texts);
    }
    push_span_shadow(texts, shadow);
    texts.push(UiText { text, x, y, color, scale });
}

// Der Text eines Abschnitts, wie er gezeichnet wird: verschleiert (obfuscated) wechselt jedes
// Zeichen ausser Leerzeichen staendig gegen ein zufaelliges (Vanilla: eines gleicher Breite;
// hier eines aus derselben Gruppe, damit die Zeile nicht springt).
fn styled_text(span: &protocol::nbt::TextSpan) -> std::borrow::Cow<'_, str> {
    if span.style & protocol::nbt::STYLE_OBFUSCATED == 0 {
        return std::borrow::Cow::Borrowed(&span.text);
    }
    const GRUPPEN: [&str; 3] = ["0123456789", "abcdeghjmnopqrsuvwxyz", "ABCDEFGHJKLMNOPQRSTUVWXYZ"];
    let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_millis() / 50) as u64;
    std::borrow::Cow::Owned(
        span.text
            .chars()
            .enumerate()
            .map(|(i, c)| {
                let Some(g) = GRUPPEN.iter().find(|g| g.contains(c)) else { return c };
                let h = (t ^ (i as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15)).wrapping_mul(0x2545_F491_4F6C_DD1D) >> 33;
                g.as_bytes()[(h % g.len() as u64) as usize] as char
            })
            .collect(),
    )
}

// Unter- und Durchstreichen eines Abschnitts von x0 bis x1 (TextRenderer.Drawer: Rechteck vom
// Pixel VOR dem ersten Zeichen bis zum Ende des Vorschubs, Leerzeichen eingeschlossen --
// genau damit bauen Server ihre Trennlinien aus "&m" und Leerzeichen). Durchgestrichen auf
// halber Zeilenhoehe, unterstrichen in der untersten Zeile der Zelle, je einen Font-Pixel dick.
fn span_lines(gpu: &GpuState, style: u8, x0: f32, x1: f32, y: f32, _color: [f32; 4], scale: f32, out: &mut dyn FnMut(Rect)) {
    if style & (protocol::nbt::STYLE_STRIKETHROUGH | protocol::nbt::STYLE_UNDERLINED) == 0 || x1 <= x0 {
        return;
    }
    let px = scale.max(1.0);
    let h = gpu.text_height(scale);
    let (links, breite) = ((x0 - px).round(), (x1 - x0 + px).round());
    if style & protocol::nbt::STYLE_STRIKETHROUGH != 0 {
        out(Rect { x: links, y: (y + h * 0.5 - px * 0.5).round(), w: breite, h: px.round() });
    }
    if style & protocol::nbt::STYLE_UNDERLINED != 0 {
        out(Rect { x: links, y: (y + h - px).round(), w: breite, h: px.round() });
    }
}

// Eine Zeile aus Abschnitten nebeneinander, mit Fettdruck und Linien. Breite wie
// span_row_width. Gibt das Ende der Zeile zurueck.
fn push_styled_row(
    gpu: &GpuState,
    spans: &[protocol::nbt::TextSpan],
    mut x: f32,
    y: f32,
    default: [f32; 4],
    scale: f32,
    texts: &mut Vec<UiText>,
    line: &mut dyn FnMut(Rect, [f32; 4]),
) -> f32 {
    for span in spans {
        let farbe = span.color.map(rgb_to_rgba).unwrap_or(default);
        let w = span_width(gpu, span, scale);
        span_lines(gpu, span.style, x, x + w, y, farbe, scale, &mut |r| line(r, farbe));
        push_styled_piece(span.style, span.shadow, styled_text(span).into_owned(), x, y, farbe, scale, texts);
        x += w;
    }
    x
}

// Vorschub eines Abschnitts: fett je Zeichen einen Font-Pixel mehr (Glyph.getAdvance(bold)).
fn span_width(gpu: &GpuState, span: &protocol::nbt::TextSpan, scale: f32) -> f32 {
    let w = gpu.measure_text(&span.text, scale);
    if span.style & protocol::nbt::STYLE_BOLD != 0 {
        w + span.text.chars().count() as f32 * scale
    } else {
        w
    }
}

fn span_row_width(gpu: &GpuState, spans: &[protocol::nbt::TextSpan], scale: f32) -> f32 {
    spans.iter().map(|s| span_width(gpu, s, scale)).sum()
}

// Breite einer Zeile, wie push_stable_spans sie setzt: als EIN Text gemessen (reservierter
// Platz wechselnder Zahlen zaehlt mit), plus der Fett-Vorschub.
fn stable_row_width(gpu: &GpuState, spans: &[protocol::nbt::TextSpan], scale: f32) -> f32 {
    let voll: String = spans.iter().map(|s| s.text.as_str()).collect();
    let fette: usize = spans.iter().filter(|s| s.style & protocol::nbt::STYLE_BOLD != 0).map(|s| s.text.chars().count()).sum();
    gpu.measure_text(&voll, scale) + fette as f32 * scale
}

// Umbrochen wird der UEBERSETZTE Text (s. i18n) -- die einzelnen Zeilen kennt die Tabelle nicht.
fn wrap_text(gpu: &GpuState, text: &str, scale: f32, max_width: f32) -> Vec<String> {
    wrap_measured(|t| gpu.measure_raw(t, scale), &i18n::tr(text), max_width)
}

// Dieselbe Umbruchregel, aber mit einer MESSFUNKTION statt der GPU -- so laesst sie sich
// pruefen, ohne ein Fenster und einen Font-Atlas aufzubauen (dieselbe Trennung wie bei
// chat_input::wrap_input_lines).
fn wrap_measured(measure: impl Fn(&str) -> f32, text: &str, max_width: f32) -> Vec<String> {
    let mut lines = Vec::new();
    let mut current = String::new();
    for word in text.split_whitespace() {
        // Ein Wort, das ALLEIN schon zu breit ist, kann keine Wortgrenze retten -- es wird
        // hart zerlegt. Ohne das laeuft genau das aus dem Bild, was man am dringendsten
        // lesen will: JSON-Kick-Gruende, Dateipfade, lange Adressen (etwa eine
        // Kick-Meldung, die rechts aus dem Fenster lief).
        if measure(word) > max_width {
            if !current.is_empty() {
                lines.push(std::mem::take(&mut current));
            }
            lines.extend(hard_break(&measure, word, max_width));
            // Der letzte Rest darf weiterwachsen, damit das naechste Wort noch anhaengt.
            current = lines.pop().unwrap_or_default();
            continue;
        }
        let candidate = if current.is_empty() { word.to_string() } else { format!("{current} {word}") };
        if measure(&candidate) > max_width && !current.is_empty() {
            lines.push(current);
            current = word.to_string();
        } else {
            current = candidate;
        }
    }
    if !current.is_empty() {
        lines.push(current);
    }
    lines
}

// Ein einzelnes, zu breites Wort zeichenweise auf `max_width` zerlegen. Zeichenweise und
// nicht byteweise: ein abgeschnittenes UTF-8-Zeichen waere kein Text mehr.
//
// Gibt IMMER mindestens eine Zeile zurueck -- auch wenn nicht einmal ein einzelnes Zeichen
// passt (winziges Panel, riesige Schrift). Sonst verschwaende der Text stillschweigend.
fn hard_break(measure: impl Fn(&str) -> f32, word: &str, max_width: f32) -> Vec<String> {
    let mut lines = Vec::new();
    let mut current = String::new();
    for ch in word.chars() {
        let candidate = format!("{current}{ch}");
        if !current.is_empty() && measure(&candidate) > max_width {
            lines.push(std::mem::take(&mut current));
            current.push(ch);
        } else {
            current = candidate;
        }
    }
    if !current.is_empty() || lines.is_empty() {
        lines.push(current);
    }
    lines
}

// Zeigt den laengsten Suffix eines (oft sehr langen) Tokens, der noch in `max_width` Pixel
// passt -- so bleibt beim Tippen/Einfuegen das Ende samt Caret sichtbar, statt aus dem Feld
// zu laufen.
fn token_display(gpu: &GpuState, token: &str, max_width: f32) -> String {
    if gpu.measure_text(token, UI_SCALE_SMALL) <= max_width {
        return token.to_string();
    }
    let chars: Vec<char> = token.chars().collect();
    for start in 0..chars.len() {
        let suffix: String = chars[start..].iter().collect();
        if gpu.measure_text(&suffix, UI_SCALE_SMALL) <= max_width {
            return suffix;
        }
    }
    String::new()
}

// Zu langen Text auf `max_width` kuerzen und mit "..." markieren -- anders als
// token_display (das VORNE abschneidet, weil beim Token das Ende interessiert) bleibt hier
// der ANFANG stehen: bei einem Servernamen/einer Adresse ist das der aussagekraeftige Teil.
// Wie ellipsize, fuer eine Zeile aus farbigen Abschnitten: was nicht passt, endet mit "..."
// in der Farbe des Abschnitts, in dem abgeschnitten wurde.
fn ellipsize_spans(gpu: &GpuState, spans: &[protocol::nbt::TextSpan], scale: f32, max_width: f32) -> Vec<protocol::nbt::TextSpan> {
    if span_row_width(gpu, spans, scale) <= max_width {
        return spans.to_vec();
    }
    let mut out: Vec<protocol::nbt::TextSpan> = Vec::new();
    let mut x = 0.0;
    for span in spans {
        let w = span_width(gpu, span, scale);
        let punkte = protocol::nbt::TextSpan { text: "...".to_string(), ..span.clone() };
        if x + w + span_width(gpu, &punkte, scale) <= max_width {
            out.push(span.clone());
            x += w;
            continue;
        }
        let chars: Vec<char> = span.text.chars().collect();
        for ende in (0..=chars.len()).rev() {
            let teil = protocol::nbt::TextSpan { text: chars[..ende].iter().collect::<String>() + "...", ..span.clone() };
            if x + span_width(gpu, &teil, scale) <= max_width || ende == 0 {
                out.push(teil);
                break;
            }
        }
        break;
    }
    out
}

fn ellipsize(gpu: &GpuState, text: &str, scale: f32, max_width: f32) -> String {
    if gpu.measure_text(text, scale) <= max_width {
        return text.to_string();
    }
    let chars: Vec<char> = text.chars().collect();
    for end in (0..chars.len()).rev() {
        let candidate: String = chars[..end].iter().collect::<String>() + "...";
        if gpu.measure_text(&candidate, scale) <= max_width {
            return candidate;
        }
    }
    String::new()
}

