// Kameraperspektive -- Vanillas F5-Umschaltung (client/option/Perspective.java: FIRST_PERSON,
// THIRD_PERSON_BACK, THIRD_PERSON_FRONT, zyklisch per next()). Jede hat ihr EIGENES Sichtfeld
// in den Einstellungen: in der 3. Person will man meist weiter sehen als im Ego-Modus.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Perspective {
    FirstPerson,
    ThirdPersonBack,
    ThirdPersonFront,
}

impl Perspective {
    const ALL: [Perspective; 3] = [Perspective::FirstPerson, Perspective::ThirdPersonBack, Perspective::ThirdPersonFront];
    // Die beiden Perspektiven mit Kameraabstand -- die Ego-Ansicht hat keinen (die Kamera
    // sitzt dort im Auge).
    const THIRD_PERSON: [Perspective; 2] = [Perspective::ThirdPersonBack, Perspective::ThirdPersonFront];

    fn next(self) -> Perspective {
        match self {
            Perspective::FirstPerson => Perspective::ThirdPersonBack,
            Perspective::ThirdPersonBack => Perspective::ThirdPersonFront,
            Perspective::ThirdPersonFront => Perspective::FirstPerson,
        }
    }

    fn is_first_person(self) -> bool {
        self == Perspective::FirstPerson
    }

    // Frontansicht: die Kamera schaut den Spieler von vorn an (Vanillas isFrontView()).
    fn is_front_view(self) -> bool {
        self == Perspective::ThirdPersonFront
    }

    // Zeile im Video-Tab, in der das Sichtfeld dieser Perspektive steht. Die 3.-Person-
    // Ansichten haben direkt darunter ihre Abstandszeile, deshalb die Luecken.
    fn fov_row(self) -> usize {
        match self {
            Perspective::FirstPerson => VIDEO_CAMERA_ROW,
            Perspective::ThirdPersonBack => VIDEO_CAMERA_ROW + 1,
            Perspective::ThirdPersonFront => VIDEO_CAMERA_ROW + 2,
        }
    }

    // Zeile des Kameraabstands unter der Projektion -- None fuer die Ego-Ansicht, die keinen
    // hat.
    fn distance_row(self) -> Option<usize> {
        match self {
            Perspective::FirstPerson => None,
            Perspective::ThirdPersonBack => Some(PROJECTION_ROW + 1),
            Perspective::ThirdPersonFront => Some(PROJECTION_ROW + 3),
        }
    }

    // Zeile der Kamerahoehe, direkt unter dem jeweiligen Abstand.
    fn y_offset_row(self) -> Option<usize> {
        match self {
            Perspective::FirstPerson => None,
            Perspective::ThirdPersonBack => Some(PROJECTION_ROW + 2),
            Perspective::ThirdPersonFront => Some(PROJECTION_ROW + 4),
        }
    }

    fn y_offset_label(self) -> &'static str {
        match self {
            Perspective::FirstPerson => "",
            Perspective::ThirdPersonBack => "Kamerahöhe (hinten)",
            Perspective::ThirdPersonFront => "Kamerahöhe (vorn)",
        }
    }

    fn distance_label(self) -> &'static str {
        match self {
            Perspective::FirstPerson => "",
            Perspective::ThirdPersonBack => "Kameraabstand (hinten)",
            Perspective::ThirdPersonFront => "Kameraabstand (vorn)",
        }
    }

    fn fov_label(self) -> &'static str {
        match self {
            Perspective::FirstPerson => "Sichtfeld (Ego)",
            Perspective::ThirdPersonBack => "Sichtfeld (3. Person)",
            Perspective::ThirdPersonFront => "Sichtfeld (3. Person, vorn)",
        }
    }

    fn hud_label(self) -> &'static str {
        match self {
            Perspective::FirstPerson => "Ego",
            Perspective::ThirdPersonBack => "3. Person",
            Perspective::ThirdPersonFront => "3. Person (vorn)",
        }
    }
}

